 1→.app {
 2→  display: flex;
 3→  flex-direction: column;
 4→  align-items: center;
 5→  justify-content: center;
 6→  min-height: 100vh;
 7→  gap: 2rem;
 8→}
 9→
10→h1 {
11→  margin: 0;
12→  font-size: 2.5rem;
13→  color: #333;
14→}
15→

  1→import { useState, useEffect, useRef } from 'react';
  2→import './Chessboard.css';
  3→import { INITIAL_BOARD, PIECE_TYPES } from './constants';
  4→import Piece from './Piece';
  5→import { playMoveSound, playCaptureSound, playNotifySound } from './sounds';
  6→import { isValidPawnMove, getEnPassantTarget, needsPromotion, indexToRowCol, isValidRookMove, isValidKnightMove, isValidBishopMove, isValidQueenMove, isValidKingMove, isKingInCheck, isCheckmate, isInsufficientMaterial, generatePositionKey } from './moveValidation';
  7→import ChessEngine from './chessEngine';
  8→import { useBlockchain } from './contexts/BlockchainContext';
  9→
 10→function Chessboard() {
 11→  const [board, setBoard] = useState(INITIAL_BOARD);
 12→  const [draggedPiece, setDraggedPiece] = useState(null);
 13→  const [draggedFrom, setDraggedFrom] = useState(null);
 14→  const [enPassantTarget, setEnPassantTarget] = useState(null);
 15→  const [promotionSquare, setPromotionSquare] = useState(null);
 16→  const [movedPieces, setMovedPieces] = useState(new Set()); // Track which pieces have moved
 17→  const [currentTurn, setCurrentTurn] = useState('white'); // Track whose turn it is
 18→  const [halfMoveClock, setHalfMoveClock] = useState(0); // For 50-move rule
 19→  const [positionHistory, setPositionHistory] = useState([generatePositionKey(INITIAL_BOARD)]); // For threefold repetition
 20→  const [validMoves, setValidMoves] = useState([]); // Highlight valid moves
 21→  const [engineColor, setEngineColor] = useState('black'); // 'white' or 'black'
 22→  const [isEngineThinking, setIsEngineThinking] = useState(false);
 23→  const [onChainMode, setOnChainMode] = useState(false); // Track if playing on-chain
 24→  const [waitingForBlockchain, setWaitingForBlockchain] = useState(false); // Track blockchain confirmation
 25→  const engineRef = useRef(null);
 26→  const lastMoveRef = useRef(null); // Store last move for promotion
 27→  const rows = 8;
 28→  const cols = 8;
 29→
 30→  // Blockchain integration
 31→  const blockchain = useBlockchain();
 32→
 33→  // Initialize engine
 34→  useEffect(() => {
 35→    if (!engineRef.current) {
 36→      engineRef.current = new ChessEngine();
 37→      engineRef.current.init();
 38→    }
 39→
 40→    return () => {
 41→      if (engineRef.current) {
 42→        engineRef.current.terminate();
 43→        engineRef.current = null;
 44→      }
 45→    };
 46→  }, []);
 47→
 48→  // Play notification sound when game ends
 49→  useEffect(() => {
 50→    const whiteInCheck = isKingInCheck(board, true);
 51→    const blackInCheck = isKingInCheck(board, false);
 52→    const whiteCheckmate = isCheckmate(board, true);
 53→    const blackCheckmate = isCheckmate(board, false);
 54→    const whiteStalemate = !whiteInCheck && whiteCheckmate;
 55→    const blackStalemate = !blackInCheck && blackCheckmate;
 56→    const fiftyMoveRule = halfMoveClock >= 100;
 57→    const currentPosition = generatePositionKey(board);
 58→    const positionCount = positionHistory.filter(pos => pos === currentPosition).length;
 59→    const threefoldRepetition = positionCount >= 3;
 60→    const insufficientMaterial = isInsufficientMaterial(board);
 61→
 62→    // Check if game has ended
 63→    const gameEnded = (whiteCheckmate && whiteInCheck) ||
 64→                      (blackCheckmate && blackInCheck) ||
 65→                      whiteStalemate ||
 66→                      blackStalemate ||
 67→                      insufficientMaterial ||
 68→                      fiftyMoveRule ||
 69→                      threefoldRepetition;
 70→
 71→    if (gameEnded) {
 72→      playNotifySound();
 73→    }
 74→  }, [board, halfMoveClock, positionHistory]);
 75→
 76→  const handleDragStart = (squareIndex, piece) => {
 77→    setDraggedPiece(piece);
 78→    setDraggedFrom(squareIndex);
 79→
 80→    // Calculate valid moves for this piece
 81→    const pieceType = Math.abs(piece);
 82→    const isWhite = piece > 0;
 83→    const moves = [];
 84→
 85→    for (let toIndex = 0; toIndex < 64; toIndex++) {
 86→      if (toIndex === squareIndex) continue;
 87→
 88→      let isValid = false;
 89→
 90→      // Check if this is a valid move based on piece type
 91→      switch (pieceType) {
 92→        case PIECE_TYPES.PAWN:
 93→          isValid = isValidPawnMove(board, squareIndex, toIndex, enPassantTarget);
 94→          break;
 95→        case PIECE_TYPES.KNIGHT:
 96→          isValid = isValidKnightMove(board, squareIndex, toIndex);
 97→          break;
 98→        case PIECE_TYPES.BISHOP:
 99→          isValid = isValidBishopMove(board, squareIndex, toIndex);
100→          break;
101→        case PIECE_TYPES.ROOK:
102→          isValid = isValidRookMove(board, squareIndex, toIndex);
103→          break;
104→        case PIECE_TYPES.QUEEN:
105→          isValid = isValidQueenMove(board, squareIndex, toIndex);
106→          break;
107→        case PIECE_TYPES.KING:
108→          const kingHasMoved = movedPieces.has(squareIndex);
109→          isValid = isValidKingMove(board, squareIndex, toIndex, kingHasMoved);
110→          break;
111→      }
112→
113→      if (isValid) {
114→        // Also check if this move would leave own king in check
115→        const testBoard = [...board];
116→        testBoard[toIndex] = piece;
117→        testBoard[squareIndex] = 0;
118→
119→        // Handle en passant in test board
120→        if (pieceType === PIECE_TYPES.PAWN && toIndex === enPassantTarget) {
121→          const { row: toRow, col: toCol } = indexToRowCol(toIndex);
122→          const capturedPawnRow = isWhite ? toRow + 1 : toRow - 1;
123→          const capturedPawnIndex = capturedPawnRow * 8 + toCol;
124→          testBoard[capturedPawnIndex] = 0;
125→        }
126→
127→        if (!isKingInCheck(testBoard, isWhite)) {
128→          moves.push(toIndex);
129→        }
130→      }
131→    }
132→
133→    setValidMoves(moves);
134→  };
135→
136→  const handleDragOver = (e) => {
137→    e.preventDefault(); // Allow drop
138→  };
139→
140→  const handlePromotion = async (pieceType) => {
141→    if (promotionSquare === null) return;
142→
143→    const newBoard = [...board];
144→    const isWhite = board[promotionSquare] > 0;
145→    newBoard[promotionSquare] = isWhite ? pieceType : -pieceType;
146→
147→    setBoard(newBoard);
148→    setPromotionSquare(null);
149→
150→    // Switch turns now that promotion is resolved
151→    const nextTurn = currentTurn === 'white' ? 'black' : 'white';
152→    setCurrentTurn(nextTurn);
153→
154→    // Update position history with the promoted board
155→    const positionKey = generatePositionKey(newBoard);
156→    setPositionHistory(prev => {
157→      const updated = [...prev];
158→      updated[updated.length - 1] = positionKey; // Replace last entry (was pre-promotion)
159→      return updated;
160→    });
161→
162→    // Submit promotion move on-chain if needed
163→    if (onChainMode && blockchain.gameId && lastMoveRef.current) {
164→      const { from, to } = lastMoveRef.current;
165→      try {
166→        setWaitingForBlockchain(true);
167→        await blockchain.makeUserMove(from, to, pieceType);
168→        console.log('✅ Promotion move confirmed on-chain');
169→      } catch (err) {
170→        console.error('❌ Failed to submit promotion on-chain:', err);
171→        setWaitingForBlockchain(false);
172→        lastMoveRef.current = null;
173→        return;
174→      } finally {
175→        setWaitingForBlockchain(false);
176→      }
177→    }
178→
179→    lastMoveRef.current = null;
180→
181→    // Trigger engine move if it's engine's turn
182→    if (nextTurn === engineColor) {
183→      setTimeout(() => makeEngineMove(newBoard, nextTurn), 500);
184→    }
185→  };
186→
187→  const handleDrop = async (squareIndex) => {
188→    if (draggedFrom === null || draggedFrom === squareIndex) {
189→      setValidMoves([]); // Clear highlights
190→      return;
191→    }
192→
193→    const pieceType = Math.abs(draggedPiece);
194→    const isWhite = draggedPiece > 0;
195→    const pieceColor = isWhite ? 'white' : 'black';
196→
197→    // Check if game is over
198→    const gameOver = isCheckmate(board, true) || isCheckmate(board, false) ||
199→                     isInsufficientMaterial(board) || halfMoveClock >= 100;
200→
201→    // Check for threefold repetition
202→    const currentPos = generatePositionKey(board);
203→    const repCount = positionHistory.filter(pos => pos === currentPos).length;
204→    const gameOverRep = repCount >= 3;
205→
206→    if (gameOver || gameOverRep) {
207→      setDraggedPiece(null);
208→      setDraggedFrom(null);
209→      setValidMoves([]);
210→      return;
211→    }
212→
213→    // Check if it's the correct player's turn
214→    if (pieceColor !== currentTurn) {
215→      setDraggedPiece(null);
216→      setDraggedFrom(null);
217→      setValidMoves([]);
218→      return;
219→    }
220→
221→    // Validate pawn moves
222→    if (pieceType === PIECE_TYPES.PAWN) {
223→      if (!isValidPawnMove(board, draggedFrom, squareIndex, enPassantTarget)) {
224→        // Invalid move - reset
225→        setDraggedPiece(null);
226→        setDraggedFrom(null);
227→        setValidMoves([]);
228→        return;
229→      }
230→    }
231→
232→    // Validate rook moves
233→    if (pieceType === PIECE_TYPES.ROOK) {
234→      if (!isValidRookMove(board, draggedFrom, squareIndex)) {
235→        // Invalid move - reset
236→        setDraggedPiece(null);
237→        setDraggedFrom(null);
238→        setValidMoves([]);
239→        return;
240→      }
241→    }
242→
243→    // Validate knight moves
244→    if (pieceType === PIECE_TYPES.KNIGHT) {
245→      if (!isValidKnightMove(board, draggedFrom, squareIndex)) {
246→        // Invalid move - reset
247→        setDraggedPiece(null);
248→        setDraggedFrom(null);
249→        setValidMoves([]);
250→        return;
251→      }
252→    }
253→
254→    // Validate bishop moves
255→    if (pieceType === PIECE_TYPES.BISHOP) {
256→      if (!isValidBishopMove(board, draggedFrom, squareIndex)) {
257→        // Invalid move - reset
258→        setDraggedPiece(null);
259→        setDraggedFrom(null);
260→        setValidMoves([]);
261→        return;
262→      }
263→    }
264→
265→    // Validate queen moves
266→    if (pieceType === PIECE_TYPES.QUEEN) {
267→      if (!isValidQueenMove(board, draggedFrom, squareIndex)) {
268→        // Invalid move - reset
269→        setDraggedPiece(null);
270→        setDraggedFrom(null);
271→        setValidMoves([]);
272→        return;
273→      }
274→    }
275→
276→    // Validate king moves
277→    if (pieceType === PIECE_TYPES.KING) {
278→      const kingHasMoved = movedPieces.has(draggedFrom);
279→      if (!isValidKingMove(board, draggedFrom, squareIndex, kingHasMoved)) {
280→        // Invalid move - reset
281→        setDraggedPiece(null);
282→        setDraggedFrom(null);
283→        setValidMoves([]);
284→        return;
285→      }
286→    }
287→
288→    // CRITICAL: Check if this move would leave own king in check
289→    const testBoard = [...board];
290→    testBoard[squareIndex] = draggedPiece;
291→    testBoard[draggedFrom] = 0;
292→
293→    // Handle en passant in test board
294→    if (pieceType === PIECE_TYPES.PAWN && squareIndex === enPassantTarget) {
295→      const { row: toRow, col: toCol } = indexToRowCol(squareIndex);
296→      const capturedPawnRow = isWhite ? toRow + 1 : toRow - 1;
297→      const capturedPawnIndex = capturedPawnRow * 8 + toCol;
298→      testBoard[capturedPawnIndex] = 0;
299→    }
300→
301→    if (isKingInCheck(testBoard, isWhite)) {
302→      // This move would leave king in check - illegal!
303→      setDraggedPiece(null);
304→      setDraggedFrom(null);
305→      return;
306→    }
307→
308→    // Check if there's a piece being captured
309→    let isCapture = board[squareIndex] !== 0;
310→
311→    // Create new board with moved piece
312→    const newBoard = [...board];
313→    newBoard[squareIndex] = draggedPiece;
314→    newBoard[draggedFrom] = 0; // Empty the original square
315→
316→    // Handle castling - move the rook as well
317→    if (pieceType === PIECE_TYPES.KING) {
318→      const { row: fromRow, col: fromCol } = indexToRowCol(draggedFrom);
319→      const { row: toRow, col: toCol } = indexToRowCol(squareIndex);
320→      const colDiff = Math.abs(toCol - fromCol);
321→
322→      if (colDiff === 2) {
323→        // Castling occurred
324→        const direction = toCol > fromCol ? 1 : -1;
325→        const rookCol = direction === 1 ? 7 : 0;
326→        const rookIndex = fromRow * 8 + rookCol;
327→        const newRookCol = toCol - direction;
328→        const newRookIndex = toRow * 8 + newRookCol;
329→
330→        // Move the rook
331→        newBoard[newRookIndex] = newBoard[rookIndex];
332→        newBoard[rookIndex] = 0;
333→      }
334→    }
335→
336→    // Handle en passant capture
337→    if (pieceType === PIECE_TYPES.PAWN && squareIndex === enPassantTarget) {
338→      // Remove the captured pawn
339→      const { row: toRow, col: toCol } = indexToRowCol(squareIndex);
340→      const capturedPawnRow = draggedPiece > 0 ? toRow + 1 : toRow - 1;
341→      const capturedPawnIndex = capturedPawnRow * 8 + toCol;
342→      newBoard[capturedPawnIndex] = 0;
343→      isCapture = true;
344→    }
345→
346→    // Check for new en passant opportunity
347→    const newEnPassantTarget = getEnPassantTarget(board, draggedFrom, squareIndex);
348→    setEnPassantTarget(newEnPassantTarget);
349→
350→    // Check if pawn needs promotion
351→    const isPromotion = needsPromotion(draggedPiece, squareIndex);
352→    if (isPromotion) {
353→      setPromotionSquare(squareIndex);
354→      // Store move for later blockchain submission after promotion selection
355→      lastMoveRef.current = { from: draggedFrom, to: squareIndex };
356→    }
357→
358→    setBoard(newBoard);
359→
360→    // Track that this piece has moved (for castling eligibility)
361→    setMovedPieces(prev => new Set([...prev, draggedFrom]));
362→
363→    // Update half-move clock for 50-move rule
364→    if (pieceType === PIECE_TYPES.PAWN || isCapture) {
365→      setHalfMoveClock(0); // Reset on pawn move or capture
366→    } else {
367→      setHalfMoveClock(prev => prev + 1);
368→    }
369→
370→    // Track position for threefold repetition
371→    const positionKey = generatePositionKey(newBoard);
372→    setPositionHistory(prev => [...prev, positionKey]);
373→
374→    setDraggedPiece(null);
375→    setDraggedFrom(null);
376→    setValidMoves([]); // Clear highlights
377→
378→    // Play appropriate sound
379→    if (isCapture) {
380→      playCaptureSound();
381→    } else {
382→      playMoveSound();
383→    }
384→
385→    // If promotion is pending, defer turn switch and engine move to handlePromotion
386→    if (isPromotion) {
387→      return;
388→    }
389→
390→    // Switch turns
391→    const nextTurn = currentTurn === 'white' ? 'black' : 'white';
392→    setCurrentTurn(nextTurn);
393→
394→    // Submit move on-chain if in blockchain mode
395→    if (onChainMode && blockchain.gameId) {
396→      try {
397→        setWaitingForBlockchain(true);
398→        // ✅ WAIT for on-chain confirmation before triggering engine
399→        await blockchain.makeUserMove(draggedFrom, squareIndex, 0);
400→        console.log('✅ User move confirmed on-chain, triggering engine...');
401→      } catch (err) {
402→        console.error('❌ Failed to submit move on-chain:', err);
403→        // Don't trigger engine if user's move failed on-chain
404→        setWaitingForBlockchain(false);
405→        return;
406→      } finally {
407→        setWaitingForBlockchain(false);
408→      }
409→    }
410→
411→    // Trigger engine move if it's engine's turn
412→    // Now this only runs AFTER user's on-chain move is confirmed!
413→    if (nextTurn === engineColor) {
414→      setTimeout(() => makeEngineMove(newBoard, nextTurn), 500);
415→    }
416→  };
417→
418→  // Make engine move
419→  const makeEngineMove = async (currentBoard, turn) => {
420→    if (!engineRef.current || isEngineThinking) return;
421→
422→    setIsEngineThinking(true);
423→
424→    try {
425→      // Calculate castling rights (simplified - assumes pieces haven't moved)
426→      const castlingRights = 'KQkq'; // TODO: Track actual castling rights
427→
428→      const move = await engineRef.current.getBestMove(
429→        currentBoard,
430→        turn,
431→        halfMoveClock,
432→        castlingRights,
433→        enPassantTarget
434→      );
435→
436→      if (move) {
437→        // Apply the engine's move
438→        const newBoard = [...currentBoard];
439→        const piece = newBoard[move.from];
440→        newBoard[move.to] = piece;
441→        newBoard[move.from] = 0;
442→
443→        // Handle castling
444→        const pieceType = Math.abs(piece);
445→        if (pieceType === PIECE_TYPES.KING) {
446→          const { row: fromRow, col: fromCol } = indexToRowCol(move.from);
447→          const { row: toRow, col: toCol } = indexToRowCol(move.to);
448→          const colDiff = Math.abs(toCol - fromCol);
449→
450→          if (colDiff === 2) {
451→            const direction = toCol > fromCol ? 1 : -1;
452→            const rookCol = direction === 1 ? 7 : 0;
453→            const rookIndex = fromRow * 8 + rookCol;
454→            const newRookCol = toCol - direction;
455→            const newRookIndex = toRow * 8 + newRookCol;
456→
457→            newBoard[newRookIndex] = newBoard[rookIndex];
458→            newBoard[rookIndex] = 0;
459→          }
460→        }
461→
462→        // Handle en passant
463→        if (pieceType === PIECE_TYPES.PAWN && move.to === enPassantTarget) {
464→          const { row: toRow, col: toCol } = indexToRowCol(move.to);
465→          const isWhite = piece > 0;
466→          const capturedPawnRow = isWhite ? toRow + 1 : toRow - 1;
467→          const capturedPawnIndex = capturedPawnRow * 8 + toCol;
468→          newBoard[capturedPawnIndex] = 0;
469→        }
470→
471→        // Check for en passant opportunity
472→        const newEnPassantTarget = getEnPassantTarget(currentBoard, move.from, move.to);
473→        setEnPassantTarget(newEnPassantTarget);
474→
475→        // Handle promotion
476→        if (move.promotion && needsPromotion(piece, move.to)) {
477→          const promotionMap = { q: PIECE_TYPES.QUEEN, r: PIECE_TYPES.ROOK, b: PIECE_TYPES.BISHOP, n: PIECE_TYPES.KNIGHT };
478→          const promotedPiece = piece > 0 ? promotionMap[move.promotion] : -promotionMap[move.promotion];
479→          newBoard[move.to] = promotedPiece;
480→        }
481→
482→        setBoard(newBoard);
483→
484→        // Track moved pieces
485→        setMovedPieces(prev => new Set([...prev, move.from]));
486→
487→        // Update half-move clock
488→        const isCapture = currentBoard[move.to] !== 0;
489→        if (pieceType === PIECE_TYPES.PAWN || isCapture) {
490→          setHalfMoveClock(0);
491→        } else {
492→          setHalfMoveClock(prev => prev + 1);
493→        }
494→
495→        // Track position
496→        const positionKey = generatePositionKey(newBoard);
497→        setPositionHistory(prev => [...prev, positionKey]);
498→
499→        // Switch turns
500→        setCurrentTurn(turn === 'white' ? 'black' : 'white');
501→
502→        // Play sound
503→        if (isCapture) {
504→          playCaptureSound();
505→        } else {
506→          playMoveSound();
507→        }
508→
509→        // Submit engine move on-chain if in blockchain mode
510→        if (onChainMode && blockchain.gameId) {
511→          let promotionValue = 0;
512→          if (move.promotion) {
513→            const promotionMap = {
514→              q: PIECE_TYPES.QUEEN,
515→              r: PIECE_TYPES.ROOK,
516→              b: PIECE_TYPES.BISHOP,
517→              n: PIECE_TYPES.KNIGHT
518→            };
519→            promotionValue = promotionMap[move.promotion] || PIECE_TYPES.QUEEN;
520→          }
521→          blockchain.makeEngineMove(move.from, move.to, promotionValue).catch(err => {
522→            console.error('Failed to submit engine move on-chain:', err);
523→          });
524→        }
525→      }
526→    } catch (error) {
527→      console.error('Engine error:', error);
528→    } finally {
529→      setIsEngineThinking(false);
530→    }
531→  };
532→
533→  const renderBoard = () => {
534→    const boardElements = [];
535→
536→    // Loop for y-axis (rows)
537→    for (let y = 0; y < rows; y++) {
538→      const row = [];
539→
540→      // Loop for x-axis (columns)
541→      for (let x = 0; x < cols; x++) {
542→        // Calculate the board array index
543→        const squareIndex = y * 8 + x;
544→        const piece = board[squareIndex];
545→
546→        // Determine square color based on position
547→        const isLight = (x + y) % 2 === 0;
548→        const isValidMove = validMoves.includes(squareIndex);
549→        const squareClass = `square ${isLight ? 'light' : 'dark'}${isValidMove ? ' valid-move' : ''}`;
550→
551→        row.push(
552→          <div
553→            key={`${x}-${y}`}
554→            className={squareClass}
555→            onDragOver={handleDragOver}
556→            onDrop={() => handleDrop(squareIndex)}
557→          >
558→            {piece !== 0 && (
559→              <Piece
560→                type={piece}
561→                onDragStart={() => handleDragStart(squareIndex, piece)}
562→              />
563→            )}
564→          </div>
565→        );
566→      }
567→
568→      boardElements.push(
569→        <div key={y} className="row">
570→          {row}
571→        </div>
572→      );
573→    }
574→
575→    return boardElements;
576→  };
577→
578→  // Check game status
579→  const whiteInCheck = isKingInCheck(board, true);
580→  const blackInCheck = isKingInCheck(board, false);
581→  const whiteCheckmate = isCheckmate(board, true);
582→  const blackCheckmate = isCheckmate(board, false);
583→
584→  // Check for stalemate (no legal moves but not in check)
585→  const whiteStalemate = !whiteInCheck && whiteCheckmate;
586→  const blackStalemate = !blackInCheck && blackCheckmate;
587→
588→  // Check for 50-move rule
589→  const fiftyMoveRule = halfMoveClock >= 100; // 100 half-moves = 50 full moves
590→
591→  // Check for threefold repetition
592→  const currentPosition = generatePositionKey(board);
593→  const positionCount = positionHistory.filter(pos => pos === currentPosition).length;
594→  const threefoldRepetition = positionCount >= 3;
595→
596→  // Check for insufficient material
597→  const insufficientMaterial = isInsufficientMaterial(board);
598→
599→  let gameStatus = '';
600→  let statusColor = '#ff6b6b'; // Default red for check/checkmate
601→
602→  if (whiteCheckmate && whiteInCheck) {
603→    gameStatus = 'Checkmate! Black wins!';
604→  } else if (blackCheckmate && blackInCheck) {
605→    gameStatus = 'Checkmate! White wins!';
606→  } else if (insufficientMaterial) {
607→    gameStatus = 'Draw - Insufficient material!';
608→    statusColor = '#4CAF50'; // Green for automatic draw
609→  } else if (fiftyMoveRule) {
610→    gameStatus = 'Draw - 50 move rule!';
611→    statusColor = '#4CAF50';
612→  } else if (threefoldRepetition) {
613→    gameStatus = 'Draw - Threefold repetition!';
614→    statusColor = '#4CAF50';
615→  } else if (whiteStalemate || blackStalemate) {
616→    gameStatus = 'Stalemate! Game is a draw!';
617→    statusColor = '#ffa500'; // Orange for stalemate
618→  } else if (whiteInCheck && currentTurn === 'white') {
619→    gameStatus = 'White is in check!';
620→  } else if (blackInCheck && currentTurn === 'black') {
621→    gameStatus = 'Black is in check!';
622→  }
623→
624→  // Handle creating on-chain game
625→  const handleStartOnChainGame = async () => {
626→    if (!blockchain.isConnected) {
627→      alert('Please connect your wallet first');
628→      return;
629→    }
630→
631→    try {
632→      const playerColor = engineColor === 'white' ? 'black' : 'white';
633→      const gameId = await blockchain.createOnChainGame(playerColor);
634→      setOnChainMode(true);
635→
636→      // If player is Black (engine is White), engine needs to make first move on-chain
637→      if (playerColor === 'black' && gameId) {
638→        console.log('Engine is White - making first move on-chain for game', gameId);
639→        // Give a small delay for transaction to settle, then make engine move
640→        setTimeout(() => {
641→          if (engineRef.current) {
642→            makeEngineMove(board, 'white');
643→          }
644→        }, 1500);
645→      }
646→    } catch (err) {
647→      console.error('Failed to create on-chain game:', err);
648→    }
649→  };
650→
651→  return (
652→    <>
653→      {/* Game Controls */}
654→      <div className="game-controls">
655→        <div className="engine-settings">
656→          <label>
657→            Play as:
658→            <select value={engineColor === 'white' ? 'black' : 'white'} onChange={(e) => setEngineColor(e.target.value === 'white' ? 'black' : 'white')}>
659→              <option value="white">White</option>
660→              <option value="black">Black</option>
661→            </select>
662→          </label>
663→          {isEngineThinking && <span className="thinking">Engine thinking...</span>}
664→          {waitingForBlockchain && <span className="blockchain-waiting">⏳ Waiting for blockchain confirmation...</span>}
665→        </div>
666→
667→        {/* Blockchain Controls */}
668→        <div className="blockchain-controls">
669→          {blockchain.isConnected ? (
670→            <>
671→              {!onChainMode ? (
672→                <button
673→                  onClick={handleStartOnChainGame}
674→                  disabled={blockchain.txPending}
675→                  className="blockchain-button"
676→                >
677→                  Start On-Chain Game
678→                </button>
679→              ) : (
680→                <div className="blockchain-info">
681→                  <span className="game-id">Game ID: {blockchain.gameId}</span>
682→                  {blockchain.engineAddress && (
683→                    <span className="engine-address" title={blockchain.engineAddress}>
684→                      Engine: {blockchain.engineAddress.slice(0, 6)}...{blockchain.engineAddress.slice(-4)}
685→                    </span>
686→                  )}
687→                </div>
688→              )}
689→              {blockchain.txStatus && (
690→                <div className="tx-status">{blockchain.txStatus}</div>
691→              )}
692→            </>
693→          ) : (
694→            <div className="blockchain-info">
695→              <span>Connect wallet to play on-chain</span>
696→            </div>
697→          )}
698→        </div>
699→      </div>
700→
701→      {gameStatus && (
702→        <div className="game-status" style={{ backgroundColor: statusColor }}>
703→          {gameStatus}
704→        </div>
705→      )}
706→
707→      <div className="chessboard">
708→        {renderBoard()}
709→      </div>
710→
711→      {promotionSquare !== null && (
712→        <div className="promotion-overlay">
713→          <div className="promotion-dialog">
714→            <h3>Promote Pawn</h3>
715→            <div className="promotion-choices">
716→              <button onClick={() => handlePromotion(PIECE_TYPES.QUEEN)}>
717→                <Piece type={board[promotionSquare] > 0 ? PIECE_TYPES.QUEEN : -PIECE_TYPES.QUEEN} />
718→                <span>Queen</span>
719→              </button>
720→              <button onClick={() => handlePromotion(PIECE_TYPES.ROOK)}>
721→                <Piece type={board[promotionSquare] > 0 ? PIECE_TYPES.ROOK : -PIECE_TYPES.ROOK} />
722→                <span>Rook</span>
723→              </button>
724→              <button onClick={() => handlePromotion(PIECE_TYPES.BISHOP)}>
725→                <Piece type={board[promotionSquare] > 0 ? PIECE_TYPES.BISHOP : -PIECE_TYPES.BISHOP} />
726→                <span>Bishop</span>
727→              </button>
728→              <button onClick={() => handlePromotion(PIECE_TYPES.KNIGHT)}>
729→                <Piece type={board[promotionSquare] > 0 ? PIECE_TYPES.KNIGHT : -PIECE_TYPES.KNIGHT} />
730→                <span>Knight</span>
731→              </button>
732→            </div>
733→          </div>
734→        </div>
735→      )}
736→    </>
737→  );
738→}
