 3→ */
 4→export async function addFluentNetwork() {
 5→  if (!window.ethereum) {
 6→    alert('MetaMask is not installed. Please install it to continue.');
 7→    return false;
 8→  }
 9→
10→  const networkConfig = {
11→    chainId: '0x51FA', // 20994 in hex
12→    chainName: 'Fluent Testnet',
13→    nativeCurrency: {
14→      name: 'ETH',
15→      symbol: 'ETH',
16→      decimals: 18,
17→    },
18→    rpcUrls: ['https://rpc.testnet.fluent.xyz/'],
19→    blockExplorerUrls: ['https://testnet.fluentscan.xyz/'],
20→  };
21→
22→  try {
23→    // Try to switch to Fluent Testnet
24→    await window.ethereum.request({
25→      method: 'wallet_switchEthereumChain',
26→      params: [{ chainId: networkConfig.chainId }],
27→    });
28→    return true;
29→  } catch (switchError) {
30→    // Network doesn't exist, add it
31→    if (switchError.code === 4902) {
32→      try {
33→        await window.ethereum.request({
34→          method: 'wallet_addEthereumChain',
35→          params: [networkConfig],
36→        });
37→        return true;
38→      } catch (addError) {
39→        console.error('Failed to add Fluent Testnet:', addError);
40→        return false;
41→      }
42→    } else {
43→      console.error('Failed to switch to Fluent Testnet:', switchError);
44→      return false;
45→    }
46→  }
47→}
