  1→import { useState, useEffect } from 'react';
  2→import { ethers } from 'ethers';
  3→import deployments from '../contracts/deployments.json';
  4→
  5→const CHESS_GAME_ABI = [
  6→  "function createGame(address whitePlayer, address blackPlayer) external returns (uint256)",
  7→  "function makeMove(uint256 gameId, uint8 fromSquare, uint8 toSquare, uint8 promotionPiece) external",
  8→  "function getGame(uint256 gameId) external view returns (tuple(uint256 gameId, address whitePlayer, address blackPlayer, uint8 currentTurn, uint8 status, uint256 moveCount, uint8 halfMoveClock, uint8 enPassantTarget, bool whiteKingMoved, bool blackKingMoved, bool whiteRookAMoved, bool whiteRookHMoved, bool blackRookAMoved, bool blackRookHMoved, uint256 createdAt, uint256 lastMoveAt))",
  9→  "function getPieceAt(uint256 gameId, uint8 square) external view returns (tuple(uint8 pieceType, uint8 color))",
 10→  "event GameCreated(uint256 indexed gameId, address indexed whitePlayer, address indexed blackPlayer)",
 11→  "event MoveMade(uint256 indexed gameId, uint256 moveNumber, address indexed player, uint8 from, uint8 to)"
 12→];
 13→
 14→// Engine wallet configuration
 15→const ENGINE_PRIVATE_KEY = import.meta.env.VITE_ENGINE_PRIVATE_KEY;
 16→const FLUENT_RPC_URL = import.meta.env.VITE_FLUENT_RPC_URL || "https://rpc.testnet.fluent.xyz/";
 17→
 18→export function useChessBlockchain() {
 19→  const [userAccount, setUserAccount] = useState(null);
 20→  const [chainId, setChainId] = useState(null);
 21→  const [gameId, setGameId] = useState(null);
 22→  const [isConnecting, setIsConnecting] = useState(false);
 23→  const [txPending, setTxPending] = useState(false);
 24→  const [txStatus, setTxStatus] = useState('');
 25→  const [error, setError] = useState(null);
 26→
 27→  // Contracts
 28→  const [userContract, setUserContract] = useState(null);
 29→  const [engineContract, setEngineContract] = useState(null);
 30→  const [engineAddress, setEngineAddress] = useState(null);
 31→
 32→  // Initialize engine contract (always available)
 33→  useEffect(() => {
 34→    const initEngine = async () => {
 35→      try {
 36→        const provider = new ethers.JsonRpcProvider(FLUENT_RPC_URL);
 37→        const engineWallet = new ethers.Wallet(ENGINE_PRIVATE_KEY, provider);
 38→        const contract = new ethers.Contract(
 39→          deployments.contracts.ChessGame,
 40→          CHESS_GAME_ABI,
 41→          engineWallet
 42→        );
 43→
 44→        setEngineContract(contract);
 45→        setEngineAddress(engineWallet.address);
 46→        console.log('Engine wallet initialized:', engineWallet.address);
 47→      } catch (err) {
 48→        console.error('Failed to initialize engine wallet:', err);
 49→      }
 50→    };
 51→
 52→    if (ENGINE_PRIVATE_KEY) {
 53→      initEngine();
 54→    }
 55→  }, []);
 56→
 57→  // Connect user wallet
 58→  const connectWallet = async () => {
 59→    try {
 60→      setIsConnecting(true);
 61→      setError(null);
 62→
 63→      if (!window.ethereum) {
 64→        throw new Error('MetaMask is not installed');
 65→      }
 66→
 67→      const accounts = await window.ethereum.request({
 68→        method: 'eth_requestAccounts',
 69→      });
 70→
 71→      const browserProvider = new ethers.BrowserProvider(window.ethereum);
 72→      const signer = await browserProvider.getSigner();
 73→      const network = await browserProvider.getNetwork();
 74→
 75→      const contract = new ethers.Contract(
 76→        deployments.contracts.ChessGame,
 77→        CHESS_GAME_ABI,
 78→        signer
 79→      );
 80→
 81→      setUserAccount(accounts[0]);
 82→      setChainId(Number(network.chainId));
 83→      setUserContract(contract);
 84→
 85→      console.log('User wallet connected:', accounts[0]);
 86→    } catch (err) {
 87→      console.error('Failed to connect wallet:', err);
 88→      setError(err.message);
 89→    } finally {
 90→      setIsConnecting(false);
 91→    }
 92→  };
 93→
 94→  // Disconnect user wallet
 95→  const disconnectWallet = () => {
 96→    setUserAccount(null);
 97→    setChainId(null);
 98→    setUserContract(null);
 99→    setGameId(null);
100→  };
101→
102→  // Create a new on-chain game
103→  const createOnChainGame = async (playerColor) => {
104→    if (!userContract || !userAccount || !engineAddress) {
105→      throw new Error('Wallet not connected or engine not initialized');
106→    }
107→
108→    try {
109→      setTxPending(true);
110→      setTxStatus('Creating game on-chain...');
111→
112→      // Determine white and black players based on color selection
113→      const whitePlayer = playerColor === 'white' ? userAccount : engineAddress;
114→      const blackPlayer = playerColor === 'white' ? engineAddress : userAccount;
115→
116→      const tx = await userContract.createGame(whitePlayer, blackPlayer);
117→      setTxStatus('Waiting for confirmation...');
118→
119→      const receipt = await tx.wait();
120→
121→      // Find GameCreated event to get gameId
122→      const event = receipt.logs.find(
123→        log => {
124→          try {
125→            const parsed = userContract.interface.parseLog(log);
126→            return parsed && parsed.name === 'GameCreated';
127→          } catch {
128→            return false;
129→          }
130→        }
131→      );
132→
133→      if (event) {
134→        const parsed = userContract.interface.parseLog(event);
135→        const newGameId = Number(parsed.args.gameId);
136→        setGameId(newGameId);
137→        setTxStatus(`Game created! ID: ${newGameId}`);
138→        setTimeout(() => setTxStatus(''), 3000);
139→        return newGameId;
140→      }
141→
142→      throw new Error('Game creation failed');
143→    } catch (err) {
144→      console.error('Error creating game:', err);
145→      setError(err.message);
146→      setTxStatus('Transaction failed');
147→      setTimeout(() => setTxStatus(''), 3000);
148→      throw err;
149→    } finally {
150→      setTxPending(false);
151→    }
152→  };
153→
154→  // Make move as user
155→  const makeUserMove = async (fromSquare, toSquare, promotionPiece = 0) => {
156→    if (!userContract || !gameId) {
157→      throw new Error('Game not initialized');
158→    }
159→
160→    try {
161→      setTxPending(true);
162→      setTxStatus('Submitting your move on-chain...');
163→
164→      console.log('Making user move:', { gameId, fromSquare, toSquare, promotionPiece, userAccount });
165→
166→      const tx = await userContract.makeMove(
167→        gameId,
168→        fromSquare,
169→        toSquare,
170→        promotionPiece
171→      );
172→
173→      setTxStatus('Waiting for confirmation...');
174→      await tx.wait();
175→
176→      setTxStatus('Move confirmed!');
177→      setTimeout(() => setTxStatus(''), 2000);
178→      return true;
179→    } catch (err) {
180→      console.error('Error making user move:', err);
181→      console.error('Move details:', { gameId, fromSquare, toSquare, promotionPiece });
182→
183→      // Decode error if possible
184→      if (err.data) {
185→        console.error('Error data:', err.data);
186→      }
187→
188→      setError(err.message);
189→      setTxStatus('Transaction failed: ' + (err.reason || err.message));
190→      setTimeout(() => setTxStatus(''), 5000);
