 23→export function useChessContract() {
 24→  const [provider, setProvider] = useState(null);
 25→  const [signer, setSigner] = useState(null);
 26→  const [chessGameContract, setChessGameContract] = useState(null);
 27→  const [chessDelegationContract, setChessDelegationContract] = useState(null);
 28→  const [account, setAccount] = useState(null);
 29→  const [chainId, setChainId] = useState(null);
 30→  const [isConnecting, setIsConnecting] = useState(false);
 31→  const [error, setError] = useState(null);
 32→
 33→  // Connect to wallet
 34→  const connectWallet = async () => {
 35→    try {
 36→      setIsConnecting(true);
 37→      setError(null);
 38→
 39→      if (!window.ethereum) {
 40→        throw new Error('MetaMask is not installed');
 41→      }
 42→
 43→      // Request account access
 44→      const accounts = await window.ethereum.request({
 45→        method: 'eth_requestAccounts',
 46→      });
 47→
 48→      const browserProvider = new ethers.BrowserProvider(window.ethereum);
 49→      const userSigner = await browserProvider.getSigner();
 50→      const network = await browserProvider.getNetwork();
 51→
 52→      setProvider(browserProvider);
 53→      setSigner(userSigner);
 54→      setAccount(accounts[0]);
 55→      setChainId(Number(network.chainId));
 56→
 57→      // Initialize contracts
 58→      const chessGame = new ethers.Contract(
 59→        deployments.contracts.ChessGame,
 60→        CHESS_GAME_ABI,
 61→        userSigner
 62→      );
 63→
 64→      const chessDelegation = new ethers.Contract(
 65→        deployments.contracts.ChessDelegation,
 66→        CHESS_DELEGATION_ABI,
 67→        userSigner
 68→      );
 69→
 70→      setChessGameContract(chessGame);
 71→      setChessDelegationContract(chessDelegation);
 72→
 73→      console.log('Connected to wallet:', accounts[0]);
 74→      console.log('Chain ID:', Number(network.chainId));
 75→    } catch (err) {
 76→      console.error('Failed to connect wallet:', err);
 77→      setError(err.message);
 78→    } finally {
 79→      setIsConnecting(false);
 80→    }
 81→  };
 82→
 83→  // Disconnect wallet
 84→  const disconnectWallet = () => {
 85→    setProvider(null);
 86→    setSigner(null);
 87→    setChessGameContract(null);
 88→    setChessDelegationContract(null);
 89→    setAccount(null);
 90→    setChainId(null);
 91→  };
 92→
 93→  // Create a new game
 94→  const createGame = async (opponentAddress) => {
 95→    if (!chessGameContract || !account) {
 96→      throw new Error('Wallet not connected');
 97→    }
 98→
 99→    try {
100→      const tx = await chessGameContract.createGame(account, opponentAddress);
101→      const receipt = await tx.wait();
102→
103→      // Find GameCreated event
104→      const event = receipt.logs.find(
105→        log => log.fragment && log.fragment.name === 'GameCreated'
106→      );
107→
108→      if (event) {
109→        return Number(event.args.gameId);
110→      }
111→
112→      throw new Error('Game creation failed');
113→    } catch (err) {
114→      console.error('Error creating game:', err);
115→      throw err;
116→    }
117→  };
118→
119→  // Make a move (standard way)
120→  const makeMove = async (gameId, fromSquare, toSquare, promotionPiece = 0) => {
121→    if (!chessGameContract) {
122→      throw new Error('Wallet not connected');
123→    }
124→
125→    try {
126→      const tx = await chessGameContract.makeMove(
127→        gameId,
128→        fromSquare,
129→        toSquare,
130→        promotionPiece
131→      );
132→      await tx.wait();
133→      return true;
134→    } catch (err) {
135→      console.error('Error making move:', err);
136→      throw err;
137→    }
138→  };
139→
140→  // Make a move using EIP-7702 delegation
141→  const makeDelegatedMove = async (gameId, fromSquare, toSquare, promotionPiece = 0) => {
142→    if (!chessDelegationContract) {
143→      throw new Error('Wallet not connected');
144→    }
145→
146→    try {
147→      // Using EIP-7702, the user's EOA temporarily sets the ChessDelegation contract as code
148→      // This allows the EOA to execute complex logic while maintaining its address
149→      const tx = await chessDelegationContract.executeDelegatedMove(
150→        gameId,
151→        fromSquare,
152→        toSquare,
153→        promotionPiece
154→      );
155→      await tx.wait();
156→      return true;
157→    } catch (err) {
158→      console.error('Error making delegated move:', err);
159→      throw err;
160→    }
161→  };
162→
163→  // Get game state
164→  const getGame = async (gameId) => {
165→    if (!chessGameContract) {
166→      throw new Error('Wallet not connected');
167→    }
168→
169→    try {
170→      const game = await chessGameContract.getGame(gameId);
171→      return game;
172→    } catch (err) {
173→      console.error('Error getting game:', err);
174→      throw err;
175→    }
176→  };
177→
178→  // Get piece at square
179→  const getPieceAt = async (gameId, square) => {
180→    if (!chessGameContract) {
181→      throw new Error('Wallet not connected');
182→    }
183→
184→    try {
185→      const piece = await chessGameContract.getPieceAt(gameId, square);
186→      return piece;
187→    } catch (err) {
188→      console.error('Error getting piece:', err);
189→      throw err;
