203→      console.error('Error getting moves:', err);
204→      throw err;
205→    }
206→  };
207→
208→  // Listen to account changes
209→  useEffect(() => {
210→    if (window.ethereum) {
211→      window.ethereum.on('accountsChanged', (accounts) => {
212→        if (accounts.length === 0) {
213→          disconnectWallet();
214→        } else {
215→          setAccount(accounts[0]);
216→        }
217→      });
218→
219→      window.ethereum.on('chainChanged', () => {
220→        window.location.reload();
221→      });
222→    }
223→
224→    return () => {
225→      if (window.ethereum) {
226→        window.ethereum.removeAllListeners('accountsChanged');
227→        window.ethereum.removeAllListeners('chainChanged');
228→      }
229→    };
230→  }, []);
231→
232→  return {
233→    // State
234→    provider,
235→    signer,
236→    account,
237→    chainId,
238→    isConnecting,
239→    error,
240→    isConnected: !!account,
241→
242→    // Contracts
243→    chessGameContract,
244→    chessDelegationContract,
245→
246→    // Functions
247→    connectWallet,
248→    disconnectWallet,
249→    createGame,
250→    makeMove,
251→    makeDelegatedMove,
252→    getGame,
