  5→const SESSION_KEY_STORAGE = 'chess_session_key';
  6→const SESSION_EXPIRY_HOURS = 24;
  7→
  8→// EIP-712 Domain for ChessGameV3
  9→const getDomain = (chainId, contractAddress) => ({
 10→  name: 'ChessGameV3',
 11→  version: '3',
 12→  chainId,
 13→  verifyingContract: contractAddress
 14→});
 15→
 16→// EIP-712 Types for session key authorization
 17→const sessionKeyTypes = {
 18→  AuthorizeSessionKey: [
 19→    { name: 'sessionKey', type: 'address' },
 20→    { name: 'expiresAt', type: 'uint256' }
 21→  ]
 22→};
 23→
