 35→export function useSessionKeys() {
 36→  const [sessionWallet, setSessionWallet] = useState(null);
 37→  const [isAuthorized, setIsAuthorized] = useState(false);
 38→  const [expiresAt, setExpiresAt] = useState(null);
 39→
 40→  // Load or create session wallet
 41→  useEffect(() => {
 42→    loadOrCreateSessionKey();
 43→  }, []);
 44→
 45→  const loadOrCreateSessionKey = () => {
 46→    try {
 47→      // Try to load existing session key from storage
 48→      const stored = sessionStorage.getItem(SESSION_KEY_STORAGE);
 49→
 50→      if (stored) {
 51→        const data = JSON.parse(stored);
 52→        const wallet = new ethers.Wallet(data.privateKey);
 53→
 54→        // Check if expired
 55→        if (Date.now() < data.expiresAt) {
 56→          setSessionWallet(wallet);
 57→          setExpiresAt(data.expiresAt);
 58→          setIsAuthorized(true);
 59→          console.log('🔑 Session key loaded:', wallet.address);
 60→          return;
 61→        } else {
 62→          console.log('⏰ Session key expired, creating new one');
 63→          sessionStorage.removeItem(SESSION_KEY_STORAGE);
 64→        }
 65→      }
 66→
 67→      // Create new session wallet
 68→      const newWallet = ethers.Wallet.createRandom();
 69→      setSessionWallet(newWallet);
 70→      console.log('🔑 New session key created:', newWallet.address);
 71→
 72→    } catch (err) {
 73→      console.error('Failed to load/create session key:', err);
 74→      // Create fresh wallet on error
 75→      const newWallet = ethers.Wallet.createRandom();
 76→      setSessionWallet(newWallet);
 77→    }
 78→  };
 79→
 80→  /**
 81→   * Authorize the session key with the user's main wallet
 82→   * User signs ONCE, then session key can sign all moves automatically
 83→   */
 84→  const authorizeSessionKey = async (userSigner, chainId, contractAddress) => {
 85→    if (!sessionWallet) {
 86→      throw new Error('Session wallet not initialized');
 87→    }
 88→
 89→    try {
 90→      console.log('🔐 Requesting session key authorization...');
 91→      console.log('  Session key:', sessionWallet.address);
 92→
 93→      // Calculate expiration (24 hours from now)
 94→      const expiresAtTimestamp = Math.floor(Date.now() / 1000) + (SESSION_EXPIRY_HOURS * 60 * 60);
 95→
 96→      // Create authorization message
 97→      const message = {
 98→        sessionKey: sessionWallet.address,
 99→        expiresAt: expiresAtTimestamp
100→      };
101→
102→      const domain = getDomain(chainId, contractAddress);
103→
104→      // User signs ONCE to authorize the session key
105→      console.log('📝 Please sign to authorize session key (ONE TIME ONLY)');
106→      const signature = await userSigner.signTypedData(domain, sessionKeyTypes, message);
107→      const sig = ethers.Signature.from(signature);
108→
109→      console.log('✅ Session key authorized! Submitting to contract...');
110→
111→      // Submit authorization to contract via relayer
112→      const response = await fetch(`${RELAYER_URL}/relay/authorize-session-key`, {
113→        method: 'POST',
114→        headers: { 'Content-Type': 'application/json' },
115→        body: JSON.stringify({
116→          sessionKey: sessionWallet.address,
117→          expiresAt: expiresAtTimestamp,
118→          v: sig.v,
119→          r: sig.r,
120→          s: sig.s
121→        })
122→      });
123→
124→      const data = await response.json();
125→
126→      if (!data.success) {
127→        throw new Error(data.error || 'Failed to authorize session key');
128→      }
129→
130→      // Save to storage
131→      const expiresAtMs = expiresAtTimestamp * 1000;
132→      sessionStorage.setItem(SESSION_KEY_STORAGE, JSON.stringify({
133→        privateKey: sessionWallet.privateKey,
134→        address: sessionWallet.address,
135→        expiresAt: expiresAtMs
136→      }));
137→
138→      setIsAuthorized(true);
139→      setExpiresAt(expiresAtMs);
140→
141→      console.log('✅ Session key authorized on-chain!');
142→      console.log('💡 No more wallet popups for the next 24 hours!');
143→
144→      return true;
145→    } catch (err) {
146→      console.error('Failed to authorize session key:', err);
147→      throw err;
148→    }
149→  };
150→
151→  /**
152→   * Sign a move with the session key (NO wallet popup!)
153→   */
154→  const signMoveWithSessionKey = async (gameId, fromSquare, toSquare, promotionPiece, nonce, chainId, contractAddress) => {
155→    if (!sessionWallet) {
156→      throw new Error('Session wallet not initialized');
157→    }
158→
159→    if (!isAuthorized) {
160→      throw new Error('Session key not authorized');
161→    }
162→
163→    try {
