168→        toSquare,
169→        promotionPiece,
170→        nonce
171→      };
172→
173→      const domain = getDomain(chainId, contractAddress);
174→
175→      // Sign with session key (NO popup - happens instantly!)
176→      const signature = await sessionWallet.signTypedData(domain, moveTypes, message);
177→
178→      console.log('✅ Move signed automatically with session key (no popup!)');
179→
180→      return signature;
181→    } catch (err) {
182→      console.error('Failed to sign move with session key:', err);
183→      throw err;
184→    }
185→  };
186→
187→  /**
188→   * Revoke the session key
189→   */
190→  const revokeSessionKey = () => {
191→    sessionStorage.removeItem(SESSION_KEY_STORAGE);
192→    setSessionWallet(null);
193→    setIsAuthorized(false);
194→    setExpiresAt(null);
195→    console.log('🔒 Session key revoked');
196→  };
