```jsx
import { useState, useEffect, useRef } from 'react';
import './Chessboard.css';
import { INITIAL_BOARD, PIECE_TYPES } from './constants';
import Piece from './Piece';
import { playMoveSound, playCaptureSound, playNotifySound } from './sounds';
import { isValidPawnMove, getEnPassantTarget, needsPromotion, indexToRowCol, isValidRookMove, isValidKnightMove, isValidBishopMove, isValidQueenMove, isValidKingMove, isKingInCheck, isCheckmate, isInsufficientMaterial, generatePositionKey } from './moveValidation';
import ChessEngine from './chessEngine';
import { useBlockchain } from './contexts/BlockchainContext';

function Chessboard() {
  const [board, setBoard] = useState(INITIAL_BOARD);
  const [draggedPiece, setDraggedPiece] = useState(null);
  const [draggedFrom, setDraggedFrom] = useState(null);
  const [enPassantTarget, setEnPassantTarget] = useState(null);
  const [promotionSquare, setPromotionSquare] = useState(null);
  const [movedPieces, setMovedPieces] = useState(new Set()); // Track which pieces have moved
  const [currentTurn, setCurrentTurn] = useState('white'); // Track whose turn it is
  const [halfMoveClock, setHalfMoveClock] = useState(0); // For 50-move rule
  const [positionHistory, setPositionHistory] = useState([generatePositionKey(INITIAL_BOARD)]); // For threefold repetition
  const [validMoves, setValidMoves] = useState([]); // Highlight valid moves
  const [engineColor, setEngineColor] = useState('black'); // 'white' or 'black'
  const [isEngineThinking, setIsEngineThinking] = useState(false);
  const [onChainMode, setOnChainMode] = useState(false); // Track if playing on-chain
  const [waitingForBlockchain, setWaitingForBlockchain] = useState(false); // Track blockchain confirmation
  const engineRef = useRef(null);
  const lastMoveRef = useRef(null); // Store last move for promotion
  const rows = 8;
  const cols = 8;

  // Blockchain integration
  const blockchain = useBlockchain();

  // Initialize engine
  useEffect(() => {
    if (!engineRef.current) {
      engineRef.current = new ChessEngine();
      engineRef.current.init();
    }

    return () => {
      if (engineRef.current) {
        engineRef.current.terminate();
        engineRef.current = null;
      }
    };
  }, []);

  // Play notification sound when game ends
  useEffect(() => {
    const whiteInCheck = isKingInCheck(board, true);
    const blackInCheck = isKingInCheck(board, false);
    const whiteCheckmate = isCheckmate(board, true);
    const blackCheckmate = isCheckmate(board, false);
    const whiteStalemate = !whiteInCheck && whiteCheckmate;
    const blackStalemate = !blackInCheck && blackCheckmate;
    const fiftyMoveRule = halfMoveClock >= 100;
    const currentPosition = generatePositionKey(board);
    const positionCount = positionHistory.filter(pos => pos === currentPosition).length;
    const threefoldRepetition = positionCount >= 3;
    const insufficientMaterial = isInsufficientMaterial(board);

    // Check if game has ended
    const gameEnded = (whiteCheckmate && whiteInCheck) ||
                      (blackCheckmate && blackInCheck) ||
                      whiteStalemate ||
                      blackStalemate ||
                      insufficientMaterial ||
                      fiftyMoveRule ||
                      threefoldRepetition;

    if (gameEnded) {
      playNotifySound();
    }
  }, [board, halfMoveClock, positionHistory]);

  const handleDragStart = (squareIndex, piece) => {
    setDraggedPiece(piece);
    setDraggedFrom(squareIndex);

    // Calculate valid moves for this piece
    const pieceType = Math.abs(piece);
    const isWhite = piece > 0;
    const moves = [];

    for (let toIndex = 0; toIndex < 64; toIndex++) {
      if (toIndex === squareIndex) continue;

      let isValid = false;

      // Check if this is a valid move based on piece type
      switch (pieceType) {
        case PIECE_TYPES.PAWN:
          isValid = isValidPawnMove(board, squareIndex, toIndex, enPassantTarget);
          break;
        case PIECE_TYPES.KNIGHT:
          isValid = isValidKnightMove(board, squareIndex, toIndex);
          break;
        case PIECE_TYPES.BISHOP:
          isValid = isValidBishopMove(board, squareIndex, toIndex);
          break;
        case PIECE_TYPES.ROOK:
          isValid = isValidRookMove(board, squareIndex, toIndex);
          break;
        case PIECE_TYPES.QUEEN:
          isValid = isValidQueenMove(board, squareIndex, toIndex);
          break;
        case PIECE_TYPES.KING:
          const kingHasMoved = movedPieces.has(squareIndex);
          isValid = isValidKingMove(board, squareIndex, toIndex, kingHasMoved);
          break;
      }

      if (isValid) {
        // Also check if this move would leave own king in check
        const testBoard = [...board];
        testBoard[toIndex] = piece;
        testBoard[squareIndex] = 0;

        // Handle en passant in test board
        if (pieceType === PIECE_TYPES.PAWN && toIndex === enPassantTarget) {
          const { row: toRow, col: toCol } = indexToRowCol(toIndex);
          const capturedPawnRow = isWhite ? toRow + 1 : toRow - 1;
          const capturedPawnIndex = capturedPawnRow * 8 + toCol;
          testBoard[capturedPawnIndex] = 0;
        }

        if (!isKingInCheck(testBoard, isWhite)) {
          moves.push(toIndex);
        }
      }
    }

    setValidMoves(moves);
  };

  const handleDragOver = (e) => {
    e.preventDefault(); // Allow drop
  };

  const handlePromotion = async (pieceType) => {
    if (promotionSquare === null) return;

    const newBoard = [...board];
    const isWhite = board[promotionSquare] > 0;
    newBoard[promotionSquare] = isWhite ? pieceType : -pieceType;

    setBoard(newBoard);
    setPromotionSquare(null);

    // Switch turns now that promotion is resolved
    const nextTurn = currentTurn === 'white' ? 'black' : 'white';
    setCurrentTurn(nextTurn);

    // Update position history with the promoted board
    const positionKey = generatePositionKey(newBoard);
    setPositionHistory(prev => {
      const updated = [...prev];
      updated[updated.length - 1] = positionKey; // Replace last entry (was pre-promotion)
      return updated;
    });

    // Submit promotion move on-chain if needed
    if (onChainMode && blockchain.gameId && lastMoveRef.current) {
      const { from, to } = lastMoveRef.current;
      try {
        setWaitingForBlockchain(true);
        await blockchain.makeUserMove(from, to, pieceType);
        console.log('✅ Promotion move confirmed on-chain');
      } catch (err) {
        console.error('❌ Failed to submit promotion on-chain:', err);
        setWaitingForBlockchain(false);
        lastMoveRef.current = null;
        return;
      } finally {
        setWaitingForBlockchain(false);
      }
    }

    lastMoveRef.current = null;

    // Trigger engine move if it's engine's turn
    if (nextTurn === engineColor) {
      setTimeout(() => makeEngineMove(newBoard, nextTurn), 500);
    }
  };

  const handleDrop = async (squareIndex) => {
    if (draggedFrom === null || draggedFrom === squareIndex) {
      setValidMoves([]); // Clear highlights
      return;
    }

    const pieceType = Math.abs(draggedPiece);
    const isWhite = draggedPiece > 0;
    const pieceColor = isWhite ? 'white' : 'black';

    // Check if game is over
    const gameOver = isCheckmate(board, true) || isCheckmate(board, false) ||
                     isInsufficientMaterial(board) || halfMoveClock >= 100;

    // Check for threefold repetition
    const currentPos = generatePositionKey(board);
    const repCount = positionHistory.filter(pos => pos === currentPos).length;
    const gameOverRep = repCount >= 3;

    if (gameOver || gameOverRep) {
      setDraggedPiece(null);
      setDraggedFrom(null);
      setValidMoves([]);
      return;
    }

    // Check if it's the correct player's turn
    if (pieceColor !== currentTurn) {
      setDraggedPiece(null);
      setDraggedFrom(null);
      setValidMoves([]);
      return;
    }

    // Validate pawn moves
    if (pieceType === PIECE_TYPES.PAWN) {
      if (!isValidPawnMove(board, draggedFrom, squareIndex, enPassantTarget)) {
        // Invalid move - reset
        setDraggedPiece(null);
        setDraggedFrom(null);
        setValidMoves([]);
        return;
      }
    }

    // Validate rook moves
    if (pieceType === PIECE_TYPES.ROOK) {
      if (!isValidRookMove(board, draggedFrom, squareIndex)) {
        // Invalid move - reset
        setDraggedPiece(null);
        setDraggedFrom(null);
        setValidMoves([]);
        return;
      }
    }

    // Validate knight moves
    if (pieceType === PIECE_TYPES.KNIGHT) {
      if (!isValidKnightMove(board, draggedFrom, squareIndex)) {
        // Invalid move - reset
        setDraggedPiece(null);
        setDraggedFrom(null);
        setValidMoves([]);
        return;
      }
    }

    // Validate bishop moves
    if (pieceType === PIECE_TYPES.BISHOP) {
      if (!isValidBishopMove(board, draggedFrom, squareIndex)) {
        // Invalid move - reset
        setDraggedPiece(null);
        setDraggedFrom(null);
        setValidMoves([]);
        return;
      }
    }

    // Validate queen moves
    if (pieceType === PIECE_TYPES.QUEEN) {
      if (!isValidQueenMove(board, draggedFrom, squareIndex)) {
        // Invalid move - reset
        setDraggedPiece(null);
        setDraggedFrom(null);
        setValidMoves([]);
        return;
      }
    }

    // Validate king moves
    if (pieceType === PIECE_TYPES.KING) {
      const kingHasMoved = movedPieces.has(draggedFrom);
      if (!isValidKingMove(board, draggedFrom, squareIndex, kingHasMoved)) {
        // Invalid move - reset
        setDraggedPiece(null);
        setDraggedFrom(null);
        setValidMoves([]);
        return;
      }
    }

    // CRITICAL: Check if this move would leave own king in check
    const testBoard = [...board];
    testBoard[squareIndex] = draggedPiece;
    testBoard[draggedFrom] = 0;

    // Handle en passant in test board
    if (pieceType === PIECE_TYPES.PAWN && squareIndex === enPassantTarget) {
      const { row: toRow, col: toCol } = indexToRowCol(squareIndex);
      const capturedPawnRow = isWhite ? toRow + 1 : toRow - 1;
      const capturedPawnIndex = capturedPawnRow * 8 + toCol;
      testBoard[capturedPawnIndex] = 0;
    }

    if (isKingInCheck(testBoard, isWhite)) {
      // This move would leave king in check - illegal!
      setDraggedPiece(null);
      setDraggedFrom(null);
      return;
    }

    // Check if there's a piece being captured
    let isCapture = board[squareIndex] !== 0;

    // Create new board with moved piece
    const newBoard = [...board];
    newBoard[squareIndex] = draggedPiece;
    newBoard[draggedFrom] = 0; // Empty the original square

    // Handle castling - move the rook as well
    if (pieceType === PIECE_TYPES.KING) {
      const { row: fromRow, col: fromCol } = indexToRowCol(draggedFrom);
      const { row: toRow, col: toCol } = indexToRowCol(squareIndex);
      const colDiff = Math.abs(toCol - fromCol);

      if (colDiff === 2) {
        // Castling occurred
        const direction = toCol > fromCol ? 1 : -1;
        const rookCol = direction === 1 ? 7 : 0;
        const rookIndex = fromRow * 8 + rookCol;
        const newRookCol = toCol - direction;
        const newRookIndex = toRow * 8 + newRookCol;

        // Move the rook
        newBoard[newRookIndex] = newBoard[rookIndex];
        newBoard[rookIndex] = 0;
      }
    }

    // Handle en passant capture
    if (pieceType === PIECE_TYPES.PAWN && squareIndex === enPassantTarget) {
      // Remove the captured pawn
      const { row: toRow, col: toCol } = indexToRowCol(squareIndex);
      const capturedPawnRow = draggedPiece > 0 ? toRow + 1 : toRow - 1;
      const capturedPawnIndex = capturedPawnRow * 8 + toCol;
      newBoard[capturedPawnIndex] = 0;
      isCapture = true;
    }

    // Check for new en passant opportunity
    const newEnPassantTarget = getEnPassantTarget(board, draggedFrom, squareIndex);
    setEnPassantTarget(newEnPassantTarget);

    // Check if pawn needs promotion
    const isPromotion = needsPromotion(draggedPiece, squareIndex);
    if (isPromotion) {
      setPromotionSquare(squareIndex);
      // Store move for later blockchain submission after promotion selection
      lastMoveRef.current = { from: draggedFrom, to: squareIndex };
    }

    setBoard(newBoard);

    // Track that this piece has moved (for castling eligibility)
    setMovedPieces(prev => new Set([...prev, draggedFrom]));

    // Update half-move clock for 50-move rule
    if (pieceType === PIECE_TYPES.PAWN || isCapture) {
      setHalfMoveClock(0); // Reset on pawn move or capture
    } else {
      setHalfMoveClock(prev => prev + 1);
    }

    // Track position for threefold repetition
    const positionKey = generatePositionKey(newBoard);
    setPositionHistory(prev => [...prev, positionKey]);

    setDraggedPiece(null);
    setDraggedFrom(null);
    setValidMoves([]); // Clear highlights

    // Play appropriate sound
    if (isCapture) {
      playCaptureSound();
    } else {
      playMoveSound();
    }

    // If promotion is pending, defer turn switch and engine move to handlePromotion
    if (isPromotion) {
      return;
    }

    // Switch turns
    const nextTurn = currentTurn === 'white' ? 'black' : 'white';
    setCurrentTurn(nextTurn);

    // Submit move on-chain if in blockchain mode
    if (onChainMode && blockchain.gameId) {
      try {
        setWaitingForBlockchain(true);
        // ✅ WAIT for on-chain confirmation before triggering engine
        await blockchain.makeUserMove(draggedFrom, squareIndex, 0);
        console.log('✅ User move confirmed on-chain, triggering engine...');
      } catch (err) {
        console.error('❌ Failed to submit move on-chain:', err);
        // Don't trigger engine if user's move failed on-chain
        setWaitingForBlockchain(false);
        return;
      } finally {
        setWaitingForBlockchain(false);
      }
    }

    // Trigger engine move if it's engine's turn
    // Now this only runs AFTER user's on-chain move is confirmed!
    if (nextTurn === engineColor) {
      setTimeout(() => makeEngineMove(newBoard, nextTurn), 500);
    }
  };

  // Make engine move
  const makeEngineMove = async (currentBoard, turn) => {
    if (!engineRef.current || isEngineThinking) return;

    setIsEngineThinking(true);

    try {
      // Calculate castling rights (simplified - assumes pieces haven't moved)
      const castlingRights = 'KQkq'; // TODO: Track actual castling rights

      const move = await engineRef.current.getBestMove(
        currentBoard,
        turn,
        halfMoveClock,
        castlingRights,
        enPassantTarget
      );

      if (move) {
        // Apply the engine's move
        const newBoard = [...currentBoard];
        const piece = newBoard[move.from];
        newBoard[move.to] = piece;
        newBoard[move.from] = 0;

        // Handle castling
        const pieceType = Math.abs(piece);
        if (pieceType === PIECE_TYPES.KING) {
          const { row: fromRow, col: fromCol } = indexToRowCol(move.from);
          const { row: toRow, col: toCol } = indexToRowCol(move.to);
          const colDiff = Math.abs(toCol - fromCol);

          if (colDiff === 2) {
            const direction = toCol > fromCol ? 1 : -1;
            const rookCol = direction === 1 ? 7 : 0;
            const rookIndex = fromRow * 8 + rookCol;
            const newRookCol = toCol - direction;
            const newRookIndex = toRow * 8 + newRookCol;

            newBoard[newRookIndex] = newBoard[rookIndex];
            newBoard[rookIndex] = 0;
          }
        }

        // Handle en passant
        if (pieceType === PIECE_TYPES.PAWN && move.to === enPassantTarget) {
          const { row: toRow, col: toCol } = indexToRowCol(move.to);
          const isWhite = piece > 0;
          const capturedPawnRow = isWhite ? toRow + 1 : toRow - 1;
          const capturedPawnIndex = capturedPawnRow * 8 + toCol;
          newBoard[capturedPawnIndex] = 0;
        }

        // Check for en passant opportunity
        const newEnPassantTarget = getEnPassantTarget(currentBoard, move.from, move.to);
        setEnPassantTarget(newEnPassantTarget);

        // Handle promotion
        if (move.promotion && needsPromotion(piece, move.to)) {
          const promotionMap = { q: PIECE_TYPES.QUEEN, r: PIECE_TYPES.ROOK, b: PIECE_TYPES.BISHOP, n: PIECE_TYPES.KNIGHT };
          const promotedPiece = piece > 0 ? promotionMap[move.promotion] : -promotionMap[move.promotion];
          newBoard[move.to] = promotedPiece;
        }

        setBoard(newBoard);

        // Track moved pieces
        setMovedPieces(prev => new Set([...prev, move.from]));

        // Update half-move clock
        const isCapture = currentBoard[move.to] !== 0;
        if (pieceType === PIECE_TYPES.PAWN || isCapture) {
          setHalfMoveClock(0);
        } else {
          setHalfMoveClock(prev => prev + 1);
        }

        // Track position
        const positionKey = generatePositionKey(newBoard);
        setPositionHistory(prev => [...prev, positionKey]);

        // Switch turns
        setCurrentTurn(turn === 'white' ? 'black' : 'white');

        // Play sound
        if (isCapture) {
          playCaptureSound();
        } else {
          playMoveSound();
        }

        // Submit engine move on-chain if in blockchain mode
        if (onChainMode && blockchain.gameId) {
          let promotionValue = 0;
          if (move.promotion) {
            const promotionMap = {
              q: PIECE_TYPES.QUEEN,
              r: PIECE_TYPES.ROOK,
              b: PIECE_TYPES.BISHOP,
              n: PIECE_TYPES.KNIGHT
            };
            promotionValue = promotionMap[move.promotion] || PIECE_TYPES.QUEEN;
          }
          blockchain.makeEngineMove(move.from, move.to, promotionValue).catch(err => {
            console.error('Failed to submit engine move on-chain:', err);
          });
        }
      }
    } catch (error) {
      console.error('Engine error:', error);
    } finally {
      setIsEngineThinking(false);
    }
  };

  const renderBoard = () => {
    const boardElements = [];

    // Loop for y-axis (rows)
    for (let y = 0; y < rows; y++) {
      const row = [];

      // Loop for x-axis (columns)
      for (let x = 0; x < cols; x++) {
        // Calculate the board array index
        const squareIndex = y * 8 + x;
        const piece = board[squareIndex];

        // Determine square color based on position
        const isLight = (x + y) % 2 === 0;
        const isValidMove = validMoves.includes(squareIndex);
        const squareClass = `square ${isLight ? 'light' : 'dark'}${isValidMove ? ' valid-move' : ''}`;

        row.push(
          <div
            key={`${x}-${y}`}
            className={squareClass}
            onDragOver={handleDragOver}
            onDrop={() => handleDrop(squareIndex)}
          >
            {piece !== 0 && (
              <Piece
                type={piece}
                onDragStart={() => handleDragStart(squareIndex, piece)}
              />
            )}
          </div>
        );
      }

      boardElements.push(
        <div key={y} className="row">
          {row}
        </div>
      );
    }

    return boardElements;
  };

  // Check game status
  const whiteInCheck = isKingInCheck(board, true);
  const blackInCheck = isKingInCheck(board, false);
  const whiteCheckmate = isCheckmate(board, true);
  const blackCheckmate = isCheckmate(board, false);

  // Check for stalemate (no legal moves but not in check)
  const whiteStalemate = !whiteInCheck && whiteCheckmate;
  const blackStalemate = !blackInCheck && blackCheckmate;

  // Check for 50-move rule
  const fiftyMoveRule = halfMoveClock >= 100; // 100 half-moves = 50 full moves

  // Check for threefold repetition
  const currentPosition = generatePositionKey(board);
  const positionCount = positionHistory.filter(pos => pos === currentPosition).length;
  const threefoldRepetition = positionCount >= 3;

  // Check for insufficient material
  const insufficientMaterial = isInsufficientMaterial(board);

  let gameStatus = '';
  let statusColor = '#ff6b6b'; // Default red for check/checkmate

  if (whiteCheckmate && whiteInCheck) {
    gameStatus = 'Checkmate! Black wins!';
  } else if (blackCheckmate && blackInCheck) {
    gameStatus = 'Checkmate! White wins!';
  } else if (insufficientMaterial) {
    gameStatus = 'Draw - Insufficient material!';
    statusColor = '#4CAF50'; // Green for automatic draw
  } else if (fiftyMoveRule) {
    gameStatus = 'Draw - 50 move rule!';
    statusColor = '#4CAF50';
  } else if (threefoldRepetition) {
    gameStatus = 'Draw - Threefold repetition!';
    statusColor = '#4CAF50';
  } else if (whiteStalemate || blackStalemate) {
    gameStatus = 'Stalemate! Game is a draw!';
    statusColor = '#ffa500'; // Orange for stalemate
  } else if (whiteInCheck && currentTurn === 'white') {
    gameStatus = 'White is in check!';
  } else if (blackInCheck && currentTurn === 'black') {
    gameStatus = 'Black is in check!';
  }

  // Handle creating on-chain game
  const handleStartOnChainGame = async () => {
    if (!blockchain.isConnected) {
      alert('Please connect your wallet first');
      return;
    }

    try {
      const playerColor = engineColor === 'white' ? 'black' : 'white';
      const gameId = await blockchain.createOnChainGame(playerColor);
      setOnChainMode(true);

      // If player is Black (engine is White), engine needs to make first move on-chain
      if (playerColor === 'black' && gameId) {
        console.log('Engine is White - making first move on-chain for game', gameId);
        // Give a small delay for transaction to settle, then make engine move
        setTimeout(() => {
          if (engineRef.current) {
            makeEngineMove(board, 'white');
          }
        }, 1500);
      }
    } catch (err) {
      console.error('Failed to create on-chain game:', err);
    }
  };

  return (
    <>
      {/* Game Controls */}
      <div className="game-controls">
        <div className="engine-settings">
          <label>
            Play as:
            <select value={engineColor === 'white' ? 'black' : 'white'} onChange={(e) => setEngineColor(e.target.value === 'white' ? 'black' : 'white')}>
              <option value="white">White</option>
              <option value="black">Black</option>
            </select>
          </label>
          {isEngineThinking && <span className="thinking">Engine thinking...</span>}
          {waitingForBlockchain && <span className="blockchain-waiting">⏳ Waiting for blockchain confirmation...</span>}
        </div>

        {/* Blockchain Controls */}
        <div className="blockchain-controls">
          {blockchain.isConnected ? (
            <>
              {!onChainMode ? (
                <button
                  onClick={handleStartOnChainGame}
                  disabled={blockchain.txPending}
                  className="blockchain-button"
                >
                  Start On-Chain Game
                </button>
              ) : (
                <div className="blockchain-info">
                  <span className="game-id">Game ID: {blockchain.gameId}</span>
                  {blockchain.engineAddress && (
                    <span className="engine-address" title={blockchain.engineAddress}>
                      Engine: {blockchain.engineAddress.slice(0, 6)}...{blockchain.engineAddress.slice(-4)}
                    </span>
                  )}
                </div>
              )}
              {blockchain.txStatus && (
                <div className="tx-status">{blockchain.txStatus}</div>
              )}
            </>
          ) : (
            <div className="blockchain-info">
              <span>Connect wallet to play on-chain</span>
            </div>
          )}
        </div>
      </div>

      {gameStatus && (
        <div className="game-status" style={{ backgroundColor: statusColor }}>
          {gameStatus}
        </div>
      )}

      <div className="chessboard">
        {renderBoard()}
      </div>

      {promotionSquare !== null && (
        <div className="promotion-overlay">
          <div className="promotion-dialog">
            <h3>Promote Pawn</h3>
            <div className="promotion-choices">
              <button onClick={() => handlePromotion(PIECE_TYPES.QUEEN)}>
                <Piece type={board[promotionSquare] > 0 ? PIECE_TYPES.QUEEN : -PIECE_TYPES.QUEEN} />
                <span>Queen</span>
              </button>
              <button onClick={() => handlePromotion(PIECE_TYPES.ROOK)}>
                <Piece type={board[promotionSquare] > 0 ? PIECE_TYPES.ROOK : -PIECE_TYPES.ROOK} />
                <span>Rook</span>
              </button>
              <button onClick={() => handlePromotion(PIECE_TYPES.BISHOP)}>
                <Piece type={board[promotionSquare] > 0 ? PIECE_TYPES.BISHOP : -PIECE_TYPES.BISHOP} />
                <span>Bishop</span>
              </button>
              <button onClick={() => handlePromotion(PIECE_TYPES.KNIGHT)}>
                <Piece type={board[promotionSquare] > 0 ? PIECE_TYPES.KNIGHT : -PIECE_TYPES.KNIGHT} />
                <span>Knight</span>
              </button>
            </div>
          </div>
        </div>
      )}
    </>
  );
}

export default Chessboard;
