  6→import { isValidPawnMove, getEnPassantTarget, needsPromotion, indexToRowCol, isValidRookMove, isValidKnightMove, isValidBishopMove, isValidQueenMove, isValidKingMove, isKingInCheck, isCheckmate, isInsufficientMaterial, generatePositionKey } from './moveValidation';
  7→import ChessEngine from './chessEngine';
  8→import { useBlockchain } from './contexts/BlockchainContext';
  9→
 10→function Chessboard() {
 11→  const [board, setBoard] = useState(INITIAL_BOARD);
 12→  const [draggedPiece, setDraggedPiece] = useState(null);
 13→  const [draggedFrom, setDraggedFrom] = useState(null);
 14→  const [enPassantTarget, setEnPassantTarget] = useState(null);
 15→  const [promotionSquare, setPromotionSquare] = useState(null);
 16→  const [movedPieces, setMovedPieces] = useState(new Set()); // Track which pieces have moved
 17→  const [currentTurn, setCurrentTurn] = useState('white'); // Track whose turn it is
 18→  const [halfMoveClock, setHalfMoveClock] = useState(0); // For 50-move rule
 19→  const [positionHistory, setPositionHistory] = useState([generatePositionKey(INITIAL_BOARD)]); // For threefold repetition
 20→  const [validMoves, setValidMoves] = useState([]); // Highlight valid moves
 21→  const [engineColor, setEngineColor] = useState('black'); // 'white' or 'black'
 22→  const [isEngineThinking, setIsEngineThinking] = useState(false);
 23→  const [onChainMode, setOnChainMode] = useState(false); // Track if playing on-chain
 24→  const [waitingForBlockchain, setWaitingForBlockchain] = useState(false); // Track blockchain confirmation
 25→  const engineRef = useRef(null);
 26→  const lastMoveRef = useRef(null); // Store last move for promotion
 27→  const rows = 8;
 28→  const cols = 8;
 29→
 30→  // Blockchain integration
 31→  const blockchain = useBlockchain();
 32→
 33→  // Initialize engine
 34→  useEffect(() => {
 35→    if (!engineRef.current) {
 36→      engineRef.current = new ChessEngine();
 37→      engineRef.current.init();
 38→    }
 39→
 40→    return () => {
 41→      if (engineRef.current) {
 42→        engineRef.current.terminate();
 43→        engineRef.current = null;
 44→      }
 45→    };
 46→  }, []);
 47→
 48→  // Play notification sound when game ends
 49→  useEffect(() => {
 50→    const whiteInCheck = isKingInCheck(board, true);
 51→    const blackInCheck = isKingInCheck(board, false);
 52→    const whiteCheckmate = isCheckmate(board, true);
 53→    const blackCheckmate = isCheckmate(board, false);
 54→    const whiteStalemate = !whiteInCheck && whiteCheckmate;
 55→    const blackStalemate = !blackInCheck && blackCheckmate;
 56→    const fiftyMoveRule = halfMoveClock >= 100;
 57→    const currentPosition = generatePositionKey(board);
 58→    const positionCount = positionHistory.filter(pos => pos === currentPosition).length;
 59→    const threefoldRepetition = positionCount >= 3;
 60→    const insufficientMaterial = isInsufficientMaterial(board);
 61→
 62→    // Check if game has ended
 63→    const gameEnded = (whiteCheckmate && whiteInCheck) ||
 64→                      (blackCheckmate && blackInCheck) ||
 65→                      whiteStalemate ||
 66→                      blackStalemate ||
 67→                      insufficientMaterial ||
 68→                      fiftyMoveRule ||
 69→                      threefoldRepetition;
 70→
 71→    if (gameEnded) {
 72→      playNotifySound();
 73→    }
 74→  }, [board, halfMoveClock, positionHistory]);
 75→
 76→  const handleDragStart = (squareIndex, piece) => {
 77→    setDraggedPiece(piece);
 78→    setDraggedFrom(squareIndex);
 79→
 80→    // Calculate valid moves for this piece
 81→    const pieceType = Math.abs(piece);
 82→    const isWhite = piece > 0;
 83→    const moves = [];
 84→
 85→    for (let toIndex = 0; toIndex < 64; toIndex++) {
 86→      if (toIndex === squareIndex) continue;
 87→
 88→      let isValid = false;
 89→
 90→      // Check if this is a valid move based on piece type
 91→      switch (pieceType) {
 92→        case PIECE_TYPES.PAWN:
 93→          isValid = isValidPawnMove(board, squareIndex, toIndex, enPassantTarget);
 94→          break;
 95→        case PIECE_TYPES.KNIGHT:
 96→          isValid = isValidKnightMove(board, squareIndex, toIndex);
 97→          break;
 98→        case PIECE_TYPES.BISHOP:
 99→          isValid = isValidBishopMove(board, squareIndex, toIndex);
100→          break;
101→        case PIECE_TYPES.ROOK:
102→          isValid = isValidRookMove(board, squareIndex, toIndex);
103→          break;
104→        case PIECE_TYPES.QUEEN:
105→          isValid = isValidQueenMove(board, squareIndex, toIndex);
106→          break;
107→        case PIECE_TYPES.KING:
108→          const kingHasMoved = movedPieces.has(squareIndex);
109→          isValid = isValidKingMove(board, squareIndex, toIndex, kingHasMoved);
110→          break;
111→      }
112→
113→      if (isValid) {
114→        // Also check if this move would leave own king in check
115→        const testBoard = [...board];
116→        testBoard[toIndex] = piece;
117→        testBoard[squareIndex] = 0;
118→
119→        // Handle en passant in test board
120→        if (pieceType === PIECE_TYPES.PAWN && toIndex === enPassantTarget) {
121→          const { row: toRow, col: toCol } = indexToRowCol(toIndex);
122→          const capturedPawnRow = isWhite ? toRow + 1 : toRow - 1;
