131→    }
132→
133→    setValidMoves(moves);
134→  };
135→
136→  const handleDragOver = (e) => {
137→    e.preventDefault(); // Allow drop
138→  };
139→
140→  const handlePromotion = async (pieceType) => {
141→    if (promotionSquare === null) return;
142→
143→    const newBoard = [...board];
