305→      return;
306→    }
307→
308→    // Check if there's a piece being captured
309→    let isCapture = board[squareIndex] !== 0;
310→
311→    // Create new board with moved piece
312→    const newBoard = [...board];
313→    newBoard[squareIndex] = draggedPiece;
314→    newBoard[draggedFrom] = 0; // Empty the original square
315→
316→    // Handle castling - move the rook as well
317→    if (pieceType === PIECE_TYPES.KING) {
318→      const { row: fromRow, col: fromCol } = indexToRowCol(draggedFrom);
319→      const { row: toRow, col: toCol } = indexToRowCol(squareIndex);
320→      const colDiff = Math.abs(toCol - fromCol);
321→
322→      if (colDiff === 2) {
323→        // Castling occurred
324→        const direction = toCol > fromCol ? 1 : -1;
325→        const rookCol = direction === 1 ? 7 : 0;
326→        const rookIndex = fromRow * 8 + rookCol;
327→        const newRookCol = toCol - direction;
328→        const newRookIndex = toRow * 8 + newRookCol;
329→
330→        // Move the rook
331→        newBoard[newRookIndex] = newBoard[rookIndex];
332→        newBoard[rookIndex] = 0;
333→      }
334→    }
335→
336→    // Handle en passant capture
337→    if (pieceType === PIECE_TYPES.PAWN && squareIndex === enPassantTarget) {
338→      // Remove the captured pawn
339→      const { row: toRow, col: toCol } = indexToRowCol(squareIndex);
340→      const capturedPawnRow = draggedPiece > 0 ? toRow + 1 : toRow - 1;
341→      const capturedPawnIndex = capturedPawnRow * 8 + toCol;
342→      newBoard[capturedPawnIndex] = 0;
343→      isCapture = true;
344→    }
345→
346→    // Check for new en passant opportunity
347→    const newEnPassantTarget = getEnPassantTarget(board, draggedFrom, squareIndex);
348→    setEnPassantTarget(newEnPassantTarget);
349→
350→    // Check if pawn needs promotion
351→    const isPromotion = needsPromotion(draggedPiece, squareIndex);
352→    if (isPromotion) {
353→      setPromotionSquare(squareIndex);
354→      // Store move for later blockchain submission after promotion selection
355→      lastMoveRef.current = { from: draggedFrom, to: squareIndex };
356→    }
357→
358→    setBoard(newBoard);
359→
360→    // Track that this piece has moved (for castling eligibility)
361→    setMovedPieces(prev => new Set([...prev, draggedFrom]));
362→
363→    // Update half-move clock for 50-move rule
364→    if (pieceType === PIECE_TYPES.PAWN || isCapture) {
365→      setHalfMoveClock(0); // Reset on pawn move or capture
366→    } else {
367→      setHalfMoveClock(prev => prev + 1);
368→    }
369→
370→    // Track position for threefold repetition
371→    const positionKey = generatePositionKey(newBoard);
372→    setPositionHistory(prev => [...prev, positionKey]);
373→
374→    setDraggedPiece(null);
375→    setDraggedFrom(null);
376→    setValidMoves([]); // Clear highlights
377→
378→    // Play appropriate sound
379→    if (isCapture) {
380→      playCaptureSound();
381→    } else {
382→      playMoveSound();
383→    }
384→
385→    // If promotion is pending, defer turn switch and engine move to handlePromotion
386→    if (isPromotion) {
387→      return;
388→    }
389→
390→    // Switch turns
391→    const nextTurn = currentTurn === 'white' ? 'black' : 'white';
392→    setCurrentTurn(nextTurn);
393→
394→    // Submit move on-chain if in blockchain mode
395→    if (onChainMode && blockchain.gameId) {
396→      try {
397→        setWaitingForBlockchain(true);
398→        // ✅ WAIT for on-chain confirmation before triggering engine
399→        await blockchain.makeUserMove(draggedFrom, squareIndex, 0);
400→        console.log('✅ User move confirmed on-chain, triggering engine...');
401→      } catch (err) {
402→        console.error('❌ Failed to submit move on-chain:', err);
403→        // Don't trigger engine if user's move failed on-chain
404→        setWaitingForBlockchain(false);
405→        return;
406→      } finally {
407→        setWaitingForBlockchain(false);
408→      }
409→    }
410→
411→    // Trigger engine move if it's engine's turn
412→    // Now this only runs AFTER user's on-chain move is confirmed!
413→    if (nextTurn === engineColor) {
414→      setTimeout(() => makeEngineMove(newBoard, nextTurn), 500);
415→    }
416→  };
417→
418→  // Make engine move
