79→        </div>
80→      )}
81→
82→      {view === 'playing' && activeGame && (
83→        <Chessboard
84→          key={activeGame.id}
85→          initialState={activeGame}
86→          onSave={handleSave}
87→          onGameEnd={handleGameEnd}
88→          onBackToList={handleBackToList}
89→          engineColorProp={activeGame.engineColor}
90→        />
91→      )}
92→    </div>
93→  );
94→}
95→
96→export default App;
