 1→const INDEX_KEY = 'chess_game_index';
 2→const GAME_PREFIX = 'chess_game_';
 3→
 4→function generateId() {
 5→  return Date.now().toString(36) + Math.random().toString(36).slice(2, 7);
 6→}
 7→
 8→export function createGame(engineColor) {
 9→  const id = generateId();
10→  const now = new Date().toISOString();
11→  const gameState = {
12→    id,
13→    board: null, // null = use INITIAL_BOARD default
14→    currentTurn: 'white',
15→    moveHistory: [],
16→    enPassantTarget: null,
17→    movedPieces: [],
18→    halfMoveClock: 0,
19→    positionHistory: [],
20→    engineColor,
21→    result: '*',
22→    createdAt: now,
23→    updatedAt: now,
24→  };
25→
26→  try {
27→    localStorage.setItem(GAME_PREFIX + id, JSON.stringify(gameState));
28→    const index = getIndex();
29→    index.unshift({ id, createdAt: now, updatedAt: now, result: '*', moveCount: 0, engineColor });
30→    localStorage.setItem(INDEX_KEY, JSON.stringify(index));
31→  } catch (e) {
32→    console.error('Failed to save game:', e);
33→    alert('Could not save game. localStorage may be full.');
34→  }
35→
36→  return gameState;
37→}
38→
39→export function saveGame(gameState) {
40→  const now = new Date().toISOString();
41→  const updated = { ...gameState, updatedAt: now, movedPieces: [...gameState.movedPieces] };
42→
43→  try {
44→    localStorage.setItem(GAME_PREFIX + gameState.id, JSON.stringify(updated));
45→    const index = getIndex();
46→    const entry = index.find(g => g.id === gameState.id);
47→    if (entry) {
48→      entry.updatedAt = now;
49→      entry.result = gameState.result;
50→      entry.moveCount = gameState.moveHistory.length;
51→      localStorage.setItem(INDEX_KEY, JSON.stringify(index));
52→    }
53→  } catch (e) {
54→    console.error('Failed to save game:', e);
55→    alert('Could not save game. localStorage may be full.');
56→  }
57→}
58→
59→export function loadGame(gameId) {
60→  const raw = localStorage.getItem(GAME_PREFIX + gameId);
61→  if (!raw) return null;
62→  const state = JSON.parse(raw);
63→  state.movedPieces = new Set(state.movedPieces);
64→  return state;
65→}
66→
67→export function listGames() {
68→  return getIndex();
69→}
70→
71→export function deleteGame(gameId) {
72→  localStorage.removeItem(GAME_PREFIX + gameId);
73→  const index = getIndex().filter(g => g.id !== gameId);
74→  localStorage.setItem(INDEX_KEY, JSON.stringify(index));
75→}
76→
77→function getIndex() {
78→  const raw = localStorage.getItem(INDEX_KEY);
79→  return raw ? JSON.parse(raw) : [];
80→}
