### New file: `/Users/gold/VS code/claude/chess UI/src/hooks/usePublishGame.js`

A custom hook that encapsulates the entire publish-to-chain flow:

```javascript
import { useWriteContract, useAccount } from 'wagmi';
import { CHESS_LEDGER_ADDRESS, chessLedgerAbi } from '../contracts/chessLedgerAbi';

export function usePublishGame() {
  const { isConnected } = useAccount();
  const { writeContractAsync, isPending, isSuccess, error, data: txHash } = useWriteContract();

  const publishGame = async (game) => {
    if (!isConnected) {
      return { published: false, reason: 'wallet-not-connected' };
    }

    if (!CHESS_LEDGER_ADDRESS) {
      console.warn('Chess ledger contract address not configured');
      return { published: false, reason: 'no-contract-address' };
    }

    try {
      const movesString = game.moveHistory.join(' ');
      const hash = await writeContractAsync({
        address: CHESS_LEDGER_ADDRESS,
        abi: chessLedgerAbi,
        functionName: 'publishGame',
        args: [game.id, game.result, movesString, game.engineColor],
      });
      return { published: true, txHash: hash };
    } catch (err) {
      console.error('Failed to publish game on-chain:', err);
      return { published: false, reason: 'tx-failed', error: err };
    }
  };

  return { publishGame, isPending, isSuccess, error, txHash };
}
```

**Key decisions:**
- Returns a result object rather than throwing. The caller (App.jsx) can decide what to do with failures without needing try/catch.
- If wallet is not connected, returns immediately with `reason: 'wallet-not-connected'`. No silent errors, no queuing.
- The `isPending` / `isSuccess` / `txHash` are exposed for UI feedback.

