file.content:
.game-list {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 1.5rem;
  max-width: 600px;
  width: 100%;
}

.game-list h2 {
  margin: 0;
  color: #333;
  font-size: 1.8rem;
}

.new-game-btn {
  padding: 0.75rem 2rem;
  background: linear-gradient(135deg, #4CAF50 0%, #45a049 100%);
  color: white;
  border: none;
  border-radius: 8px;
  font-size: 1.1rem;
  font-weight: 600;
  cursor: pointer;
  transition: all 0.2s;
  box-shadow: 0 2px 6px rgba(0, 0, 0, 0.2);
}

.new-game-btn:hover {
  transform: translateY(-2px);
  box-shadow: 0 4px 10px rgba(0, 0, 0, 0.3);
}

.no-games {
  color: #888;
  font-size: 1rem;
}

.game-cards {
  display: flex;
  flex-direction: column;
  gap: 0.75rem;
  width: 100%;
}

.game-card {
  background: white;
  border: 2px solid #e0e0e0;
  border-radius: 10px;
  padding: 1rem 1.25rem;
  cursor: pointer;
  transition: all 0.2s;
}

.game-card:hover {
  border-color: #4CAF50;
  box-shadow: 0 2px 8px rgba(76, 175, 80, 0.2);
  transform: translateY(-1px);
}

.game-card-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 0.5rem;
}

.game-result {
  font-weight: 600;
  font-size: 0.95rem;
  padding: 0.2rem 0.6rem;
  border-radius: 4px;
}

.game-result.in-progress {
  background: #fff3e0;
  color: #e65100;
}

.game-result.finished {
  background: #e8f5e9;
  color: #2e7d32;
}

.delete-btn {
  background: none;
  border: none;
  font-size: 1.4rem;
  color: #999;
  cursor: pointer;
  padding: 0 0.4rem;
  line-height: 1;
  border-radius: 4px;
}

.delete-btn:hover {
  color: #e53935;
  background: #ffebee;
}

.game-card-body {
  display: flex;
  justify-content: space-between;
  color: #555;
  font-size: 0.9rem;
  margin-bottom: 0.4rem;
}

.game-card-footer {
  color: #999;
  font-size: 0.8rem;
  text-align: right;
}

.onchain-badge {
  display: inline-flex;
  align-items: center;
  padding: 0.15rem 0.5rem;
  background: #e3f2fd;
  color: #1565c0;
  font-size: 0.75rem;
  font-weight: 600;
  border-radius: 4px;
  text-decoration: none;
  transition: background 0.2s;
}

.onchain-badge:hover {
  background: #bbdefb;
}

