const INDEX_KEY = 'chess_game_index';
const GAME_PREFIX = 'chess_game_';

function generateId() {
  return Date.now().toString(36) + Math.random().toString(36).slice(2, 7);
}

export function createGame(engineColor) {
  const id = generateId();
  const now = new Date().toISOString();
  const gameState = {
    id,
    board: null, // null = use INITIAL_BOARD default
    currentTurn: 'white',
    moveHistory: [],
    enPassantTarget: null,
    movedPieces: [],
    halfMoveClock: 0,
    positionHistory: [],
    engineColor,
    result: '*',
    createdAt: now,
    updatedAt: now,
  };

  try {
    localStorage.setItem(GAME_PREFIX + id, JSON.stringify(gameState));
    const index = getIndex();
    index.unshift({ id, createdAt: now, updatedAt: now, result: '*', moveCount: 0, engineColor });
    localStorage.setItem(INDEX_KEY, JSON.stringify(index));
  } catch (e) {
    console.error('Failed to save game:', e);
    alert('Could not save game. localStorage may be full.');
  }

  return gameState;
}

export function saveGame(gameState) {
  const now = new Date().toISOString();
  const updated = { ...gameState, updatedAt: now, movedPieces: [...gameState.movedPieces] };

  try {
    localStorage.setItem(GAME_PREFIX + gameState.id, JSON.stringify(updated));
    const index = getIndex();
    const entry = index.find(g => g.id === gameState.id);
    if (entry) {
      entry.updatedAt = now;
      entry.result = gameState.result;
      entry.moveCount = gameState.moveHistory.length;
      localStorage.setItem(INDEX_KEY, JSON.stringify(index));
    }
  } catch (e) {
    console.error('Failed to save game:', e);
    alert('Could not save game. localStorage may be full.');
  }
}

export function loadGame(gameId) {
  const raw = localStorage.getItem(GAME_PREFIX + gameId);
  if (!raw) return null;
  const state = JSON.parse(raw);
  state.movedPieces = new Set(state.movedPieces);
  return state;
}

export function listGames() {
  return getIndex();
}

export function deleteGame(gameId) {
  localStorage.removeItem(GAME_PREFIX + gameId);
  const index = getIndex().filter(g => g.id !== gameId);
  localStorage.setItem(INDEX_KEY, JSON.stringify(index));
}

export function markGamePublished(gameId, txHash) {
  const raw = localStorage.getItem(GAME_PREFIX + gameId);
  if (!raw) return;
  const state = JSON.parse(raw);
  state.txHash = txHash;
  localStorage.setItem(GAME_PREFIX + gameId, JSON.stringify(state));

  const index = getIndex();
  const entry = index.find(g => g.id === gameId);
  if (entry) {
    entry.txHash = txHash;
    localStorage.setItem(INDEX_KEY, JSON.stringify(index));
  }
}

function getIndex() {
  const raw = localStorage.getItem(INDEX_KEY);
  return raw ? JSON.parse(raw) : [];
}

import { useState, useEffect } from 'react';
import { listGames, deleteGame, loadGame } from '../utils/gameManager';
import './GameList.css';

function GameList({ onNewGame, onResumeGame }) {
  const [games, setGames] = useState([]);


  useEffect(() => {
    setGames(listGames());
  }, []);

  const handleDelete = (e, gameId) => {
    e.stopPropagation();
    deleteGame(gameId);
    setGames(listGames());
  };

  const handleShare = (e, game) => {
    e.stopPropagation();
    const fullGame = loadGame(game.id);
    if (!fullGame) return;

    const history = fullGame.moveHistory || [];
    const playerColor = game.engineColor === 'white' ? 'black' : 'white';
    const d = new Date(game.updatedAt);
    const dateStr = `${d.getFullYear()}.${String(d.getMonth() + 1).padStart(2, '0')}.${String(d.getDate()).padStart(2, '0')}`;
    const timeStr = `${String(d.getHours()).padStart(2, '0')}:${String(d.getMinutes()).padStart(2, '0')}:${String(d.getSeconds()).padStart(2, '0')}`;

    const humanName = playerColor === 'white' ? 'Human' : 'Engine (Stockfish)';
    const engineName = playerColor === 'white' ? 'Engine (Stockfish)' : 'Human';

    let txSection = '';
    if (game.txHash) {
      txSection = `\n\t<key>Blockchain</key>\n\t<string>Fluent Testnet</string>\n\t<key>TxHash</key>\n\t<string>${game.txHash}</string>\n\t<key>Explorer</key>\n\t<string>https://testnet.fluentscan.xyz/tx/${game.txHash}</string>`;
    }

    const xml = `<?xml version="1.0" encoding="UTF-8"?>
<!DOCTYPE plist PUBLIC "-//Apple//DTD PLIST 1.0//EN" "http://www.apple.com/DTDs/PropertyList-1.0.dtd">
<plist version="1.0">
<dict>
\t<key>White</key>
\t<string>${humanName}</string>
\t<key>WhiteType</key>
\t<string>${playerColor === 'white' ? 'human' : 'program'}</string>
\t<key>Black</key>
\t<string>${engineName}</string>
\t<key>BlackType</key>
\t<string>${playerColor === 'black' ? 'human' : 'program'}</string>
\t<key>Event</key>
\t<string>vs Stockfish</string>
\t<key>StartDate</key>
\t<string>${dateStr}</string>
\t<key>StartTime</key>
\t<string>${timeStr}</string>
\t<key>Result</key>
\t<string>${game.result}</string>
\t<key>Variant</key>
\t<string>normal</string>
\t<key>Moves</key>
\t<string>
${history.join('\n')}
\t</string>${txSection}
</dict>
</plist>`;

    const blob = new Blob([xml], { type: 'application/xml' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `Game ${game.id}.game`;
    a.click();
    URL.revokeObjectURL(url);
  };

  const resultLabel = (result) => {
    if (result === '1-0') return 'White wins';
    if (result === '0-1') return 'Black wins';
    if (result === '1/2-1/2') return 'Draw';
    return 'In progress';
  };

  const formatDate = (iso) => {
    const d = new Date(iso);
    return d.toLocaleDateString(undefined, { month: 'short', day: 'numeric', hour: '2-digit', minute: '2-digit' });
  };

  return (
    <div className="game-list">
      <h2>Your Games</h2>
      <button className="new-game-btn" onClick={onNewGame}>+ New Game</button>

      {games.length === 0 && <p className="no-games">No saved games yet. Start a new game!</p>}

      <div className="game-cards">
        {games.map(game => (
          <div key={game.id} className="game-card" onClick={() => onResumeGame(game.id)}>
            <div className="game-card-header">
              <span className={`game-result ${game.result === '*' ? 'in-progress' : 'finished'}`}>
                {resultLabel(game.result)}
              </span>
              {game.txHash && (
                <a
                  href={`https://testnet.fluentscan.xyz/tx/${game.txHash}`}
                  target="_blank"
                  rel="noopener noreferrer"
                  className="onchain-badge"
                  onClick={(e) => e.stopPropagation()}
                  title="View on-chain transaction"
                >
                  On-chain
                </a>
              )}
              <div className="card-actions">
                {game.result !== '*' && (
                  <button
                    className="share-btn"
                    onClick={(e) => handleShare(e, game)}
                    title="Download game record as XML"
                  >
                    Share
                  </button>
                )}
                <button className="delete-btn" onClick={(e) => handleDelete(e, game.id)} title="Delete game">
                  &times;
                </button>
              </div>
            </div>
            <div className="game-card-body">
              <span>Playing as {game.engineColor === 'white' ? 'Black' : 'White'}</span>
              <span>{game.moveCount} moves</span>
            </div>
            <div className="game-card-footer">
              {formatDate(game.updatedAt)}
            </div>
          </div>
        ))}
      </div>
    </div>
  );
}

export default GameList;

