  1→import { useState } from 'react';
  2→
  3→import './App.css';
  4→import Chessboard from './Chessboard';
  5→import GameList from './components/GameList';
  6→import PasskeyButton from './components/PasskeyButton';
  7→import { createGame, saveGame, loadGame, markGamePublished } from './utils/gameManager';
  8→import { usePasskeyAuth } from './hooks/usePasskeyAuth';
  9→import { usePasskeyPublish } from './hooks/usePasskeyPublish';
 10→
 11→function App() {
 12→  const [view, setView] = useState('list'); // 'list' | 'setup' | 'playing'
 13→  const [activeGame, setActiveGame] = useState(null);
 14→  const [setupColor, setSetupColor] = useState('white');
 15→  const [publishStatus, setPublishStatus] = useState(null); // null | 'pending' | 'success' | 'error'
 16→
 17→  const passkey = usePasskeyAuth();
 18→  const { publishGame: passkeyPublish } = usePasskeyPublish({
 19→    account: passkey.account,
 20→    credentialId: passkey.credentialId,
 21→    rawId: passkey.rawId,
 22→  });
 23→
 24→  const handleNewGame = () => {
 25→    setView('setup');
 26→  };
 27→
 28→  const handleStartGame = () => {
 29→    const engineColor = setupColor === 'white' ? 'black' : 'white';
 30→    const game = createGame(engineColor);
 31→    setActiveGame(game);
 32→    setView('playing');
 33→  };
 34→
 35→  const handleResumeGame = (gameId) => {
 36→    const game = loadGame(gameId);
 37→    if (game) {
 38→      setActiveGame(game);
 39→      setView('playing');
 40→    }
 41→  };
 42→
 43→  const handleSave = (state) => {
 44→    if (!activeGame) return;
 45→    saveGame({ ...state, id: activeGame.id, engineColor: activeGame.engineColor, createdAt: activeGame.createdAt });
 46→  };
 47→
 48→  const handleGameEnd = async (result) => {
 49→    if (!activeGame) return;
 50→
 51→    // Load the latest auto-saved state (triggerSave already saved the correct final board)
 52→    // Don't use stale activeGame — it holds the initial state from when the game was loaded
 53→    const latestState = loadGame(activeGame.id);
 54→    if (latestState) {
 55→      latestState.result = result;
 56→      saveGame(latestState);
 57→    }
 58→    setActiveGame(prev => ({ ...prev, result }));
 59→
 60→    // Use latest state for on-chain publish (has actual move history)
 61→    const finishedGame = latestState || { ...activeGame, result };
 62→
 63→    // Attempt on-chain publish — passkey takes priority if authenticated
 64→    setPublishStatus('pending');
 65→    const publishResult = await passkeyPublish(finishedGame);
 66→
 67→    if (publishResult.published) {
 68→      setPublishStatus('success');
 69→      markGamePublished(finishedGame.id, publishResult.txHash);
 70→      setTimeout(() => setPublishStatus(null), 4000);
 71→    } else if (['no-contract-address', 'passkey-not-authenticated'].includes(publishResult.reason)) {
 72→      setPublishStatus(null); // Silently skip
 73→    } else {
 74→      setPublishStatus('error');
 75→      setTimeout(() => setPublishStatus(null), 5000);
 76→    }
 77→  };
 78→
 79→  const handleBackToList = () => {
 80→    setActiveGame(null);
 81→    setPublishStatus(null);
 82→    setView('list');
 83→  };
 84→
 85→  return (
 86→    <div className="app">
 87→      <header className="app-header">
 88→        <h1>Chess Board</h1>
 89→        <PasskeyButton
 90→          isAuthenticated={passkey.isAuthenticated}
 91→          account={passkey.account}
 92→          username={passkey.username}
 93→          onSignup={passkey.signup}
 94→          onLogin={passkey.login}
 95→          onLogout={passkey.logout}
 96→        />
 97→      </header>
 98→
 99→      {publishStatus && (
100→        <div className={`publish-toast ${publishStatus}`}>
101→          {publishStatus === 'pending' && 'Publishing game on-chain...'}
102→          {publishStatus === 'success' && 'Game published on-chain!'}
103→          {publishStatus === 'error' && 'Failed to publish on-chain'}
104→        </div>
105→      )}
106→
107→      {view === 'list' && (
108→        <GameList onNewGame={handleNewGame} onResumeGame={handleResumeGame} />
109→      )}
110→
111→      {view === 'setup' && (
112→        <div className="new-game-setup">
113→          <h2>New Game</h2>
114→          <div className="color-picker">
115→            <label>Play as:</label>
116→            <div className="color-options">
117→              <button
118→                className={`color-option ${setupColor === 'white' ? 'selected' : ''}`}
119→                onClick={() => setSetupColor('white')}
120→              >
121→                White
122→              </button>
123→              <button
124→                className={`color-option ${setupColor === 'black' ? 'selected' : ''}`}
125→                onClick={() => setSetupColor('black')}
126→              >
127→                Black
128→              </button>
129→            </div>
130→          </div>
131→          <div className="setup-actions">
132→            <button className="setup-back" onClick={() => setView('list')}>Cancel</button>
133→            <button className="setup-start" onClick={handleStartGame}>Start Game</button>
134→          </div>
135→        </div>
136→      )}
137→
138→      {view === 'playing' && activeGame && (
139→        <Chessboard
140→          key={activeGame.id}
141→          initialState={activeGame}
142→          onSave={handleSave}
143→          onGameEnd={handleGameEnd}
144→          onBackToList={handleBackToList}
145→          engineColorProp={activeGame.engineColor}
146→        />
147→      )}
148→    </div>
149→  );
150→}
151→
152→export default App;
