  5→function GameList({ onNewGame, onResumeGame }) {
  6→  const [games, setGames] = useState([]);
  7→
  8→
  9→  useEffect(() => {
 10→    setGames(listGames());
 11→  }, []);
 12→
 13→  const handleDelete = (e, gameId) => {
 14→    e.stopPropagation();
 15→    deleteGame(gameId);
 16→    setGames(listGames());
 17→  };
 18→
 19→  const handleClearAll = () => {
 20→    if (!window.confirm('Delete all saved games?')) return;
 21→    clearAllGames();
 22→    setGames([]);
 23→  };
 24→
 25→  const handleShare = (e, game) => {
 26→    e.stopPropagation();
 27→    const fullGame = loadGame(game.id);
 28→    if (!fullGame) return;
 29→
 30→    const history = fullGame.moveHistory || [];
 31→    const playerColor = game.engineColor === 'white' ? 'black' : 'white';
 32→    const d = new Date(game.updatedAt);
 33→    const dateStr = `${d.getFullYear()}.${String(d.getMonth() + 1).padStart(2, '0')}.${String(d.getDate()).padStart(2, '0')}`;
 34→    const timeStr = `${String(d.getHours()).padStart(2, '0')}:${String(d.getMinutes()).padStart(2, '0')}:${String(d.getSeconds()).padStart(2, '0')}`;
 35→
 36→    const humanName = playerColor === 'white' ? 'Human' : 'Engine (Stockfish)';
 37→    const engineName = playerColor === 'white' ? 'Engine (Stockfish)' : 'Human';
 38→
 39→    let txSection = '';
 40→    if (game.txHash) {
 41→      txSection = `\n\t<key>Blockchain</key>\n\t<string>Fluent Testnet</string>\n\t<key>TxHash</key>\n\t<string>${game.txHash}</string>\n\t<key>Explorer</key>\n\t<string>https://testnet.fluentscan.xyz/tx/${game.txHash}</string>`;
 42→    }
 43→
 44→    const xml = `<?xml version="1.0" encoding="UTF-8"?>
 45→<!DOCTYPE plist PUBLIC "-//Apple//DTD PLIST 1.0//EN" "http://www.apple.com/DTDs/PropertyList-1.0.dtd">
 46→<plist version="1.0">
 47→<dict>
 48→\t<key>White</key>
 49→\t<string>${humanName}</string>
 50→\t<key>WhiteType</key>
 51→\t<string>${playerColor === 'white' ? 'human' : 'program'}</string>
 52→\t<key>Black</key>
 53→\t<string>${engineName}</string>
 54→\t<key>BlackType</key>
 55→\t<string>${playerColor === 'black' ? 'human' : 'program'}</string>
 56→\t<key>Event</key>
 57→\t<string>vs Stockfish</string>
 58→\t<key>StartDate</key>
 59→\t<string>${dateStr}</string>
 60→\t<key>StartTime</key>
 61→\t<string>${timeStr}</string>
 62→\t<key>Result</key>
 63→\t<string>${game.result}</string>
 64→\t<key>Variant</key>
 65→\t<string>normal</string>
 66→\t<key>Moves</key>
 67→\t<string>
 68→${history.join('\n')}
 69→\t</string>${txSection}
 70→</dict>
 71→</plist>`;
 72→
 73→    const blob = new Blob([xml], { type: 'application/xml' });
 74→    const url = URL.createObjectURL(blob);
 75→    const a = document.createElement('a');
 76→    a.href = url;
 77→    a.download = `Game ${game.id}.game`;
 78→    a.click();
 79→    URL.revokeObjectURL(url);
 80→  };
 81→
 82→  const resultLabel = (result) => {
 83→    if (result === '1-0') return 'White wins';
 84→    if (result === '0-1') return 'Black wins';
 85→    if (result === '1/2-1/2') return 'Draw';
