 99→        {games.length > 0 && (
100→          <button className="clear-all-btn" onClick={handleClearAll}>Clear All</button>
101→        )}
102→      </div>
103→
104→      {games.length === 0 && <p className="no-games">No saved games yet. Start a new game!</p>}
105→
106→      <div className="game-cards">
107→        {games.map(game => (
108→          <div key={game.id} className="game-card" onClick={() => onResumeGame(game.id)}>
109→            <div className="game-card-header">
110→              <span className={`game-result ${game.result === '*' ? 'in-progress' : 'finished'}`}>
111→                {resultLabel(game.result)}
112→              </span>
113→              {game.txHash && (
114→                <a
115→                  href={`https://testnet.fluentscan.xyz/tx/${game.txHash}`}
116→                  target="_blank"
117→                  rel="noopener noreferrer"
118→                  className="onchain-badge"
